  --rtmsy-para-gap: .75em;
  --rtmsy-dialog-weight: 600;
}

/* 본문: RisuAI 기본 색·글꼴 변수에 테마 값을 연결합니다. */
.rtmsy {
  --risu-font-family: var(--rtmsy-font-body);
  --FontColorStandard: var(--rtmsy-ink);
  --FontColorBold: var(--rtmsy-ink);
  --FontColorItalic: var(--rtmsy-muted);
  --FontColorItalicBold: var(--rtmsy-muted);
  --FontColorQuote1: var(--rtmsy-muted);
  --FontColorQuote2: var(--rtmsy-dialog);
  position: relative;
  isolation: isolate;
  width: 100%;
  min-width: 0;
  color: var(--rtmsy-ink);
  font-family: var(--rtmsy-font-body);
  font-size: var(--rtmsy-font-size);
  line-height: var(--rtmsy-line-height);
}
.rtmsy, .rtmsy *, .rtmsy *::before, .rtmsy *::after { box-sizing: border-box; }
/* 바깥 래퍼 보정(.risu-chat > div > div)이 테마 루트를 flex로 바꾸지 않게 루트 배치를 고정합니다. */
.rtmsy.rtmsy { display: block; }
.rtmsy__content {
  min-width: 0;
  color: var(--rtmsy-ink);
  word-break: keep-all;
  overflow-wrap: anywhere;
}
.rtmsy__content .chattext {
  --tw-prose-code: var(--rtmsy-ink);
  --tw-prose-pre-code: var(--rtmsy-ink);
  --tw-prose-pre-bg: var(--rtmsy-tint);
  max-width: none;
  color: var(--rtmsy-ink);
  font-size: var(--rtmsy-font-size) !important;
  line-height: var(--rtmsy-line-height) !important;
}
.rtmsy__content :is(p, li, td, th, blockquote) {
  font-size: var(--rtmsy-font-size);
  line-height: var(--rtmsy-line-height);
}
.rtmsy__content p { margin: 0 0 var(--rtmsy-para-gap); }
.rtmsy__content p:last-child { margin-bottom: 0; }
.rtmsy__content :is(h1, h2, h3, h4, h5, h6) {
  --risu-font-family: var(--rtmsy-font-display);
  margin: 1.3em 0 .55em;
  color: var(--rtmsy-ink);
  font-family: var(--rtmsy-font-display);
  line-height: 1.4;
  font-weight: 700;
}
.rtmsy__content h1 { font-size: calc(var(--rtmsy-font-size) * 1.6); }
.rtmsy__content h2 { font-size: calc(var(--rtmsy-font-size) * 1.35); }
.rtmsy__content h3 { font-size: calc(var(--rtmsy-font-size) * 1.15); }
.rtmsy__content :is(h4, h5, h6) { font-size: var(--rtmsy-font-size); }
.rtmsy__content strong { font-weight: 700; }
.rtmsy__content em { color: var(--rtmsy-muted); }
.rtmsy__content mark[risu-mark="quote1"],
.rtmsy__content mark[risu-mark="blockquote1"] { color: var(--rtmsy-muted); background: transparent; }
.rtmsy__content mark[risu-mark="quote2"],
.rtmsy__content mark[risu-mark="blockquote2"] {
  color: var(--rtmsy-dialog);
  font-weight: var(--rtmsy-dialog-weight);
  background: transparent;
}
.rtmsy__content blockquote {
  margin: 1em 0;
  padding: .3em 1em;
  border-left: 3px solid var(--rtmsy-line);
  color: var(--rtmsy-muted);
}
.rtmsy__content :is(ul, ol) { margin: 1em 0; padding-left: 1.5em; }
.rtmsy__content li { margin: .25em 0; color: var(--rtmsy-ink); }
.rtmsy__content li::marker { color: var(--rtmsy-muted); }
.rtmsy__content a { color: var(--rtmsy-accent); text-decoration: underline; }
.rtmsy__content hr { border: 0; border-top: 1px solid var(--rtmsy-line); margin: 1.5em 0; }
.rtmsy__content code {
  --risu-font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  padding: .1em .3em;
  border-radius: .2em;
  color: var(--rtmsy-ink);
  background: var(--rtmsy-tint);
  font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  font-size: calc(var(--rtmsy-font-size) * .88);
}
.rtmsy__content pre {
  max-width: 100%;
  overflow-x: auto;
  padding: .9em 1em;
  color: var(--rtmsy-ink);
  background: var(--rtmsy-tint);
  border-radius: .35rem;
  font-size: calc(var(--rtmsy-font-size) * .88);
  line-height: 1.5;
}
.rtmsy__content pre code { padding: 0; background: transparent; color: inherit; white-space: pre; overflow-wrap: normal; }
.rtmsy__content table {
  display: block;
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
  margin: 1em 0;
}
.rtmsy__content :is(th, td) {
  padding: .5em .7em;
  color: var(--rtmsy-ink);
  border-bottom: 1px solid var(--rtmsy-line);
  text-align: left;
  vertical-align: top;
}
.rtmsy__content th { font-weight: 700; }
.rtmsy__content img { display: block; max-width: 100%; height: auto; margin: .75em auto; }
.rtmsy__content textarea.message-edit-area {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  color: var(--rtmsy-ink) !important;
  background: var(--rtmsy-edit-bg) !important;
  border: 1px solid var(--rtmsy-line);
  border-radius: .4rem;
  font: inherit;
  font-size: var(--rtmsy-font-size) !important;
  line-height: var(--rtmsy-line-height) !important;
}

/* 조작부: 생성 정보와 버튼 */
.rtmsy__footer {
  --risu-theme-textcolor2: var(--rtmsy-muted);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .4rem .75rem;
  min-width: 0;
}
.rtmsy__info, .rtmsy__actions { min-width: 0; max-width: 100%; }
.rtmsy__info > div, .rtmsy__actions > div { flex-wrap: wrap; min-width: 0; gap: .3rem; }
.rtmsy__actions > div > div { flex-wrap: wrap; min-width: 0; }
.rtmsy__footer button {
  background: transparent;
  min-height: 1.9rem;
  padding: .25rem .4rem;
  border-radius: .3rem;
  white-space: normal;
}
.rtmsy__footer button:hover { background: var(--rtmsy-tint); }
.rtmsy :is(a, button, textarea):focus-visible { outline: 2px solid var(--rtmsy-accent); outline-offset: 2px; }

/* 아바타 틀: RisuAI가 넣는 배경 이미지 칸을 틀에 맞춥니다. */
.rtmsy__portrait { overflow: hidden; background: var(--rtmsy-tint); }
.rtmsy__portrait > * {
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  background-size: cover !important;
  background-position: center 22% !important;
  border: 0 !important;
  border-radius: inherit !important;
}

.rtmsy__bg {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background: var(--rtmsy-bg-fill);
  -webkit-backdrop-filter: var(--rtmsy-blur);
  backdrop-filter: var(--rtmsy-blur);
  box-shadow: var(--rtmsy-bg-edge);
}

/* 구조: 메신저 양쪽 */


.rtmsy {
  --rtmsy-col: 44rem;
  --rtmsy-gap: clamp(1rem, 2.5vw, 2rem);
  /* PC 고정 초상: 바깥 가장자리에 붙고, 3:4 비율로 칸 폭과 높이 중 먼저 닿는 쪽까지 커집니다.
     남는 폭은 초상과 본문 사이로, 남는 높이는 위아래로 나뉩니다. */
  --rtmsy-edge: 1rem;
  --rtmsy-fixed-bottom: 5rem; /* 입력창을 피하는 아래 여백 */
  --rtmsy-fixed-w: max(8rem, min(calc((100% - var(--rtmsy-col)) / 2 - var(--rtmsy-gap) - var(--rtmsy-edge)), calc((100vh - var(--rtmsy-edge) - var(--rtmsy-fixed-bottom)) * 3 / 4)));
  --rtmsy-pad: 1rem;
  max-width: var(--rtmsy-col);
  margin: 0 auto;
  padding: .55rem 0;
}
.rtmsy__side { display: none; }
.rtmsy__main { min-width: 0; }
.rtmsy__speaker { margin-bottom: .45rem; color: var(--rtmsy-muted); font-size: .8em; font-weight: 700; letter-spacing: .02em; }
.rtmsy--char .rtmsy__speaker { color: var(--rtmsy-ink); }
/* 정규식이 넣은 조각은 스스로 숨어 있습니다. 이 테마 안에서만 드러냅니다. */
.rtmsy .x-risu-rtmsy-pair { display: block !important; height: 0; margin: 0; padding: 0; }
.rtmsy .x-risu-rtmsy-pair-char, .rtmsy .x-risu-rtmsy-pair-user {
  display: none;
  background-size: cover;
  background-position: center 22%;
}
/* 투명 토글은 PC의 가장 최근 메시지에서만 보입니다. */
.rtmsy .x-risu-rtmsy-fade { display: none; }

/* 고정 초상이 채팅 영역을 기준으로 놓이게 합니다 (이 테마가 채팅에 있을 때만 걸립니다). */
:has(> .default-chat-screen .rtmsy) { transform: translateZ(0); }

/* PC: 가장 최근 메시지 하나에서만 두 초상을 꺼내 채팅 영역 양옆에 고정합니다.
   가장 최근 메시지가 편집 중이라 이미지가 없으면 그 바로 앞 메시지가, 대화가 첫인사뿐이면 첫인사가 맡습니다. */
@media (min-width: 901px) {
  .chat-message-container:first-child .rtmsy :is(.x-risu-rtmsy-pair-char, .x-risu-rtmsy-pair-user),
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy :is(.x-risu-rtmsy-pair-char, .x-risu-rtmsy-pair-user),
  .flex-col-reverse:empty + .risu-chat .rtmsy :is(.x-risu-rtmsy-pair-char, .x-risu-rtmsy-pair-user) {
    display: block;
    position: fixed;
    z-index: 1;
    /* 입력창을 뺀 영역의 세로 가운데: 위아래를 정하고 margin auto로 가운데에 둡니다 (transform을 쓰지 않아야 토글 앵커가 맞습니다) */
    top: var(--rtmsy-edge);
    bottom: var(--rtmsy-fixed-bottom);
    margin-block: auto;
    width: var(--rtmsy-fixed-w);
    aspect-ratio: 3 / 4;
    transition: opacity .3s ease, filter .3s ease, translate .3s ease, scale .3s ease;
  }
  .chat-message-container:first-child .rtmsy .x-risu-rtmsy-pair-char,
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy .x-risu-rtmsy-pair-char,
  .flex-col-reverse:empty + .risu-chat .rtmsy .x-risu-rtmsy-pair-char {
    left: var(--rtmsy-edge);
    transform: rotate(var(--rtmsy-tilt-char));
    anchor-name: --rtmsy-portrait-char;
  }
  .chat-message-container:first-child .rtmsy .x-risu-rtmsy-pair-user,
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy .x-risu-rtmsy-pair-user,
  .flex-col-reverse:empty + .risu-chat .rtmsy .x-risu-rtmsy-pair-user {
    right: var(--rtmsy-edge);
    transform: rotate(var(--rtmsy-tilt-user));
  }
  /* 말하는 쪽: 살짝 떠오르고 아래에 옅은 그림자가 집니다.
     변주마다 쓰는 transform·box-shadow를 덮지 않도록 translate·scale·filter만 씁니다. */
  .chat-message-container:first-child .rtmsy--char .x-risu-rtmsy-pair-char,
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy--char .x-risu-rtmsy-pair-char,
  .flex-col-reverse:empty + .risu-chat .rtmsy--char .x-risu-rtmsy-pair-char,
  .chat-message-container:first-child .rtmsy--user .x-risu-rtmsy-pair-user,
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy--user .x-risu-rtmsy-pair-user,
  .flex-col-reverse:empty + .risu-chat .rtmsy--user .x-risu-rtmsy-pair-user {
    translate: 0 -4px;
    scale: 1.015;
    filter: drop-shadow(0 14px 12px rgba(0, 0, 0, .22));
  }
  /* 투명 토글: 왼쪽 초상 안쪽 왼쪽 위 귀퉁이의 작은 단추. 누르면 두 초상이 거의 투명해져 배경이 보입니다.
     초상 높이는 채팅 영역 폭에 따라 달라 CSS 계산으로는 세로 위치를 맞출 수 없으므로, 앵커 위치 지정으로 초상에 붙입니다.
     앵커를 지원하지 않는 브라우저에서는 채팅 영역 위쪽, 초상과 같은 세로선에 놓입니다. */
  .chat-message-container:first-child .rtmsy .x-risu-rtmsy-fade,
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy .x-risu-rtmsy-fade,
  .flex-col-reverse:empty + .risu-chat .rtmsy .x-risu-rtmsy-fade {
    display: block;
    position: fixed;
    z-index: 2;
    top: calc(var(--rtmsy-edge) + .6rem);
    left: calc(var(--rtmsy-edge) + .6rem);
    margin: 0;
  }
  @supports (anchor-name: --a) {
    .chat-message-container:first-child .rtmsy .x-risu-rtmsy-fade,
    .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy .x-risu-rtmsy-fade,
    .flex-col-reverse:empty + .risu-chat .rtmsy .x-risu-rtmsy-fade {
      position-anchor: --rtmsy-portrait-char;
      top: calc(anchor(top) + .6rem);
      left: calc(anchor(left) + .6rem);
    }
  }
  .rtmsy .x-risu-rtmsy-fade > summary {
    display: grid;
    place-items: center;
    width: 1.9rem;
    height: 1.9rem;
    border-radius: 50%;
    list-style: none;
    cursor: pointer;
    color: #fff;
    font-size: .95rem;
    line-height: 1;
    background: rgba(0, 0, 0, .32);
    -webkit-backdrop-filter: blur(6px);
    backdrop-filter: blur(6px);
    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .25);
    opacity: .7;
    transition: opacity .2s ease, background .2s ease;
    user-select: none;
  }
  .rtmsy .x-risu-rtmsy-fade > summary::-webkit-details-marker { display: none; }
  .rtmsy .x-risu-rtmsy-fade > summary::before { content: "◐"; }
  .rtmsy .x-risu-rtmsy-fade > summary:hover,
  .rtmsy .x-risu-rtmsy-fade[open] > summary { opacity: 1; background: rgba(0, 0, 0, .5); }
  .rtmsy.rtmsy .x-risu-rtmsy-pair.x-risu-rtmsy-pair:has(> .x-risu-rtmsy-fade[open]) :is(.x-risu-rtmsy-pair-char, .x-risu-rtmsy-pair-user) {
    opacity: .08;
    translate: none;
    scale: none;
    filter: none;
  }
}

/* 휴대폰: 메시지마다 위에 두 초상이 마주 봅니다 */
@media (max-width: 900px) {
  .rtmsy.rtmsy { display: grid; }
  .rtmsy {
    --rtmsy-side-w: 6rem;
    grid-template-columns: 1fr 1fr;
    row-gap: .8rem;
    column-gap: .6rem;
    max-width: none;
    padding: var(--rtmsy-pad) 0;
  }
  .rtmsy__side { display: flex; flex-direction: row; align-items: center; gap: .6rem; min-width: 0; }
  .rtmsy__side--char { grid-column: 1; grid-row: 1; justify-content: flex-start; }
  .rtmsy__side--user { grid-column: 2; grid-row: 1; flex-direction: row-reverse; justify-content: flex-start; }
  .rtmsy__frame { position: relative; width: var(--rtmsy-side-w); flex: 0 0 auto; aspect-ratio: 3 / 4; }
  .rtmsy__portrait { width: 100%; height: 100%; border-radius: inherit; }
  .rtmsy__side-name { min-width: 0; color: var(--rtmsy-muted); font-size: .78em; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .rtmsy__main { grid-column: 1 / -1; grid-row: 2; }
  .rtmsy__speaker { display: none; }
  .rtmsy--char .rtmsy__side--char .rtmsy__side-name, .rtmsy--user .rtmsy__side--user .rtmsy__side-name { color: var(--rtmsy-ink); }
  /* 말하는 쪽 초상: 살짝 떠오르고 아래에 옅은 그림자 */
  .rtmsy--char .rtmsy__side--char .rtmsy__frame, .rtmsy--user .rtmsy__side--user .rtmsy__frame {
    translate: 0 -3px;
    scale: 1.04;
    filter: drop-shadow(0 8px 7px rgba(0, 0, 0, .2));
  }
  .rtmsy .x-risu-rtmsy-pair-char, .rtmsy .x-risu-rtmsy-pair-user {
    position: absolute;
    top: var(--rtmsy-pad);
    width: var(--rtmsy-side-w);
    aspect-ratio: 3 / 4;
  }
  .rtmsy--user .x-risu-rtmsy-pair-char { display: block; left: 0; }
  .rtmsy--char .x-risu-rtmsy-pair-user { display: block; right: 0; }
}
.rtmsy { --rtmsy-tilt-char: 0deg; --rtmsy-tilt-user: 0deg; }
.rtmsy__frame { border-radius: .7rem; background: var(--rtmsy-tint); box-shadow: 0 0 0 1px var(--rtmsy-frame), 0 6px 16px var(--rtmsy-shadow); }
.rtmsy .x-risu-rtmsy-pair-char, .rtmsy .x-risu-rtmsy-pair-user { border-radius: .8rem; box-shadow: 0 0 0 1px var(--rtmsy-frame), 0 10px 28px var(--rtmsy-shadow); }
.rtmsy__main {
  padding: 1rem 1.15rem .8rem;
  background: var(--rtmsy-panel);
  border: 1px solid var(--rtmsy-line);
  border-radius: .7rem;
  box-shadow: 0 6px 16px var(--rtmsy-shadow);
}
.rtmsy--user .rtmsy__main { background: var(--rtmsy-panel-user); }
.rtmsy__footer { margin-top: .7rem; padding-top: .5rem; border-top: 1px solid var(--rtmsy-line); font-size: .85em; }

/* ── 배색과 소재: 이 블록만 바꾸면 같은 분류의 다른 변주가 됩니다. (백색) ── */
.rtmsy {
  --rtmsy-wall: #f3f0eb;
  --rtmsy-panel: #fffdf9;
  --rtmsy-panel-user: #f7f2ea;
  --rtmsy-ink: #2b2724;
  --rtmsy-muted: #857c72;
  --rtmsy-accent: #8a6f55;
  --rtmsy-dialog: #5e4630;
  --rtmsy-frame: #e4ddd2;
  --rtmsy-shadow: rgba(60, 45, 30, .08);
  --rtmsy-line: #e5ded3;
  --rtmsy-tint: #f1ebe2;
  --rtmsy-edit-bg: #ffffff;
}

@import url("https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/variable/pretendardvariable-dynamic-subset.min.css");

/* 바깥 래퍼: 메시지 폭을 확보하고 가운데 정렬합니다. */
.risu-chat > div {
  padding: 0 .75rem;
  margin: auto;
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
}
.risu-chat > div > div {
  width: 100%;
  margin: auto;
  display: flex;
  justify-content: center;
}

/* 글꼴과 크기: 본문 글자 크기는 --rtmsy-font-size로 바꿉니다. */
.rtmsy {
  --rtmsy-bg-fill: transparent;
  --rtmsy-blur: none;
  --rtmsy-bg-edge: none;
  --rtmsy-font-body: "Pretendard Variable", "Pretendard", "Noto Sans KR", -apple-system, "Malgun Gothic", sans-serif;
  --rtmsy-font-display: "Pretendard Variable", "Pretendard", "Noto Sans KR", -apple-system, "Malgun Gothic", sans-serif;
  --rtmsy-font-size: 15.5px;
  --rtmsy-line-height: 1.75;
  --rtmsy-para-gap: .75em;
  --rtmsy-dialog-weight: 600;
}

/* 본문: RisuAI 기본 색·글꼴 변수에 테마 값을 연결합니다. */
.rtmsy {
  --risu-font-family: var(--rtmsy-font-body);
  --FontColorStandard: var(--rtmsy-ink);
  --FontColorBold: var(--rtmsy-ink);
  --FontColorItalic: var(--rtmsy-muted);
  --FontColorItalicBold: var(--rtmsy-muted);
  --FontColorQuote1: var(--rtmsy-muted);
  --FontColorQuote2: var(--rtmsy-dialog);
  position: relative;
  isolation: isolate;
  width: 100%;
  min-width: 0;
  color: var(--rtmsy-ink);
  font-family: var(--rtmsy-font-body);
  font-size: var(--rtmsy-font-size);
  line-height: var(--rtmsy-line-height);
}
.rtmsy, .rtmsy *, .rtmsy *::before, .rtmsy *::after { box-sizing: border-box; }
/* 바깥 래퍼 보정(.risu-chat > div > div)이 테마 루트를 flex로 바꾸지 않게 루트 배치를 고정합니다. */
.rtmsy.rtmsy { display: block; }
.rtmsy__content {
  min-width: 0;
  color: var(--rtmsy-ink);
  word-break: keep-all;
  overflow-wrap: anywhere;
}
.rtmsy__content .chattext {
  --tw-prose-code: var(--rtmsy-ink);
  --tw-prose-pre-code: var(--rtmsy-ink);
  --tw-prose-pre-bg: var(--rtmsy-tint);
  max-width: none;
  color: var(--rtmsy-ink);
  font-size: var(--rtmsy-font-size) !important;
  line-height: var(--rtmsy-line-height) !important;
}
.rtmsy__content :is(p, li, td, th, blockquote) {
  font-size: var(--rtmsy-font-size);
  line-height: var(--rtmsy-line-height);
}
.rtmsy__content p { margin: 0 0 var(--rtmsy-para-gap); }
.rtmsy__content p:last-child { margin-bottom: 0; }
.rtmsy__content :is(h1, h2, h3, h4, h5, h6) {
  --risu-font-family: var(--rtmsy-font-display);
  margin: 1.3em 0 .55em;
  color: var(--rtmsy-ink);
  font-family: var(--rtmsy-font-display);
  line-height: 1.4;
  font-weight: 700;
}
.rtmsy__content h1 { font-size: calc(var(--rtmsy-font-size) * 1.6); }
.rtmsy__content h2 { font-size: calc(var(--rtmsy-font-size) * 1.35); }
.rtmsy__content h3 { font-size: calc(var(--rtmsy-font-size) * 1.15); }
.rtmsy__content :is(h4, h5, h6) { font-size: var(--rtmsy-font-size); }
.rtmsy__content strong { font-weight: 700; }
.rtmsy__content em { color: var(--rtmsy-muted); }
.rtmsy__content mark[risu-mark="quote1"],
.rtmsy__content mark[risu-mark="blockquote1"] { color: var(--rtmsy-muted); background: transparent; }
.rtmsy__content mark[risu-mark="quote2"],
.rtmsy__content mark[risu-mark="blockquote2"] {
  color: var(--rtmsy-dialog);
  font-weight: var(--rtmsy-dialog-weight);
  background: transparent;
}
.rtmsy__content blockquote {
  margin: 1em 0;
  padding: .3em 1em;
  border-left: 3px solid var(--rtmsy-line);
  color: var(--rtmsy-muted);
}
.rtmsy__content :is(ul, ol) { margin: 1em 0; padding-left: 1.5em; }
.rtmsy__content li { margin: .25em 0; color: var(--rtmsy-ink); }
.rtmsy__content li::marker { color: var(--rtmsy-muted); }
.rtmsy__content a { color: var(--rtmsy-accent); text-decoration: underline; }
.rtmsy__content hr { border: 0; border-top: 1px solid var(--rtmsy-line); margin: 1.5em 0; }
.rtmsy__content code {
  --risu-font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  padding: .1em .3em;
  border-radius: .2em;
  color: var(--rtmsy-ink);
  background: var(--rtmsy-tint);
  font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  font-size: calc(var(--rtmsy-font-size) * .88);
}
.rtmsy__content pre {
  max-width: 100%;
  overflow-x: auto;
  padding: .9em 1em;
  color: var(--rtmsy-ink);
  background: var(--rtmsy-tint);
  border-radius: .35rem;
  font-size: calc(var(--rtmsy-font-size) * .88);
  line-height: 1.5;
}
.rtmsy__content pre code { padding: 0; background: transparent; color: inherit; white-space: pre; overflow-wrap: normal; }
.rtmsy__content table {
  display: block;
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
  margin: 1em 0;
}
.rtmsy__content :is(th, td) {
  padding: .5em .7em;
  color: var(--rtmsy-ink);
  border-bottom: 1px solid var(--rtmsy-line);
  text-align: left;
  vertical-align: top;
}
.rtmsy__content th { font-weight: 700; }
.rtmsy__content img { display: block; max-width: 100%; height: auto; margin: .75em auto; }
.rtmsy__content textarea.message-edit-area {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  color: var(--rtmsy-ink) !important;
  background: var(--rtmsy-edit-bg) !important;
  border: 1px solid var(--rtmsy-line);
  border-radius: .4rem;
  font: inherit;
  font-size: var(--rtmsy-font-size) !important;
  line-height: var(--rtmsy-line-height) !important;
}

/* 조작부: 생성 정보와 버튼 */
.rtmsy__footer {
  --risu-theme-textcolor2: var(--rtmsy-muted);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .4rem .75rem;
  min-width: 0;
}
.rtmsy__info, .rtmsy__actions { min-width: 0; max-width: 100%; }
.rtmsy__info > div, .rtmsy__actions > div { flex-wrap: wrap; min-width: 0; gap: .3rem; }
.rtmsy__actions > div > div { flex-wrap: wrap; min-width: 0; }
.rtmsy__footer button {
  background: transparent;
  min-height: 1.9rem;
  padding: .25rem .4rem;
  border-radius: .3rem;
  white-space: normal;
}
.rtmsy__footer button:hover { background: var(--rtmsy-tint); }
.rtmsy :is(a, button, textarea):focus-visible { outline: 2px solid var(--rtmsy-accent); outline-offset: 2px; }

/* 아바타 틀: RisuAI가 넣는 배경 이미지 칸을 틀에 맞춥니다. */
.rtmsy__portrait { overflow: hidden; background: var(--rtmsy-tint); }
.rtmsy__portrait > * {
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  background-size: cover !important;
  background-position: center 22% !important;
  border: 0 !important;
  border-radius: inherit !important;
}

.rtmsy__bg {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background: var(--rtmsy-bg-fill);
  -webkit-backdrop-filter: var(--rtmsy-blur);
  backdrop-filter: var(--rtmsy-blur);
  box-shadow: var(--rtmsy-bg-edge);
}

/* 구조: 메신저 양쪽 */


.rtmsy {
  --rtmsy-col: 44rem;
  --rtmsy-gap: clamp(1rem, 2.5vw, 2rem);
  /* PC 고정 초상: 바깥 가장자리에 붙고, 3:4 비율로 칸 폭과 높이 중 먼저 닿는 쪽까지 커집니다.
     남는 폭은 초상과 본문 사이로, 남는 높이는 위아래로 나뉩니다. */
  --rtmsy-edge: 1rem;
  --rtmsy-fixed-bottom: 5rem; /* 입력창을 피하는 아래 여백 */
  --rtmsy-fixed-w: max(8rem, min(calc((100% - var(--rtmsy-col)) / 2 - var(--rtmsy-gap) - var(--rtmsy-edge)), calc((100vh - var(--rtmsy-edge) - var(--rtmsy-fixed-bottom)) * 3 / 4)));
  --rtmsy-pad: 1rem;
  max-width: var(--rtmsy-col);
  margin: 0 auto;
  padding: .55rem 0;
}
.rtmsy__side { display: none; }
.rtmsy__main { min-width: 0; }
.rtmsy__speaker { margin-bottom: .45rem; color: var(--rtmsy-muted); font-size: .8em; font-weight: 700; letter-spacing: .02em; }
.rtmsy--char .rtmsy__speaker { color: var(--rtmsy-ink); }
/* 정규식이 넣은 조각은 스스로 숨어 있습니다. 이 테마 안에서만 드러냅니다. */
.rtmsy .x-risu-rtmsy-pair { display: block !important; height: 0; margin: 0; padding: 0; }
.rtmsy .x-risu-rtmsy-pair-char, .rtmsy .x-risu-rtmsy-pair-user {
  display: none;
  background-size: cover;
  background-position: center 22%;
}
/* 투명 토글은 PC의 가장 최근 메시지에서만 보입니다. */
.rtmsy .x-risu-rtmsy-fade { display: none; }

/* 고정 초상이 채팅 영역을 기준으로 놓이게 합니다 (이 테마가 채팅에 있을 때만 걸립니다). */
:has(> .default-chat-screen .rtmsy) { transform: translateZ(0); }

/* PC: 가장 최근 메시지 하나에서만 두 초상을 꺼내 채팅 영역 양옆에 고정합니다.
   가장 최근 메시지가 편집 중이라 이미지가 없으면 그 바로 앞 메시지가, 대화가 첫인사뿐이면 첫인사가 맡습니다. */
@media (min-width: 901px) {
  .chat-message-container:first-child .rtmsy :is(.x-risu-rtmsy-pair-char, .x-risu-rtmsy-pair-user),
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy :is(.x-risu-rtmsy-pair-char, .x-risu-rtmsy-pair-user),
  .flex-col-reverse:empty + .risu-chat .rtmsy :is(.x-risu-rtmsy-pair-char, .x-risu-rtmsy-pair-user) {
    display: block;
    position: fixed;
    z-index: 1;
    /* 입력창을 뺀 영역의 세로 가운데: 위아래를 정하고 margin auto로 가운데에 둡니다 (transform을 쓰지 않아야 토글 앵커가 맞습니다) */
    top: var(--rtmsy-edge);
    bottom: var(--rtmsy-fixed-bottom);
    margin-block: auto;
    width: var(--rtmsy-fixed-w);
    aspect-ratio: 3 / 4;
    transition: opacity .3s ease, filter .3s ease, translate .3s ease, scale .3s ease;
  }
  .chat-message-container:first-child .rtmsy .x-risu-rtmsy-pair-char,
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy .x-risu-rtmsy-pair-char,
  .flex-col-reverse:empty + .risu-chat .rtmsy .x-risu-rtmsy-pair-char {
    left: var(--rtmsy-edge);
    transform: rotate(var(--rtmsy-tilt-char));
    anchor-name: --rtmsy-portrait-char;
  }
  .chat-message-container:first-child .rtmsy .x-risu-rtmsy-pair-user,
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy .x-risu-rtmsy-pair-user,
  .flex-col-reverse:empty + .risu-chat .rtmsy .x-risu-rtmsy-pair-user {
    right: var(--rtmsy-edge);
    transform: rotate(var(--rtmsy-tilt-user));
  }
  /* 말하는 쪽: 살짝 떠오르고 아래에 옅은 그림자가 집니다.
     변주마다 쓰는 transform·box-shadow를 덮지 않도록 translate·scale·filter만 씁니다. */
  .chat-message-container:first-child .rtmsy--char .x-risu-rtmsy-pair-char,
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy--char .x-risu-rtmsy-pair-char,
  .flex-col-reverse:empty + .risu-chat .rtmsy--char .x-risu-rtmsy-pair-char,
  .chat-message-container:first-child .rtmsy--user .x-risu-rtmsy-pair-user,
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy--user .x-risu-rtmsy-pair-user,
  .flex-col-reverse:empty + .risu-chat .rtmsy--user .x-risu-rtmsy-pair-user {
    translate: 0 -4px;
    scale: 1.015;
    filter: drop-shadow(0 14px 12px rgba(0, 0, 0, .22));
  }
  /* 투명 토글: 왼쪽 초상 안쪽 왼쪽 위 귀퉁이의 작은 단추. 누르면 두 초상이 거의 투명해져 배경이 보입니다.
     초상 높이는 채팅 영역 폭에 따라 달라 CSS 계산으로는 세로 위치를 맞출 수 없으므로, 앵커 위치 지정으로 초상에 붙입니다.
     앵커를 지원하지 않는 브라우저에서는 채팅 영역 위쪽, 초상과 같은 세로선에 놓입니다. */
  .chat-message-container:first-child .rtmsy .x-risu-rtmsy-fade,
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy .x-risu-rtmsy-fade,
  .flex-col-reverse:empty + .risu-chat .rtmsy .x-risu-rtmsy-fade {
    display: block;
    position: fixed;
    z-index: 2;
    top: calc(var(--rtmsy-edge) + .6rem);
    left: calc(var(--rtmsy-edge) + .6rem);
    margin: 0;
  }
  @supports (anchor-name: --a) {
    .chat-message-container:first-child .rtmsy .x-risu-rtmsy-fade,
    .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy .x-risu-rtmsy-fade,
    .flex-col-reverse:empty + .risu-chat .rtmsy .x-risu-rtmsy-fade {
      position-anchor: --rtmsy-portrait-char;
      top: calc(anchor(top) + .6rem);
      left: calc(anchor(left) + .6rem);
    }
  }
  .rtmsy .x-risu-rtmsy-fade > summary {
    display: grid;
    place-items: center;
    width: 1.9rem;
    height: 1.9rem;
    border-radius: 50%;
    list-style: none;
    cursor: pointer;
    color: #fff;
    font-size: .95rem;
    line-height: 1;
    background: rgba(0, 0, 0, .32);
    -webkit-backdrop-filter: blur(6px);
    backdrop-filter: blur(6px);
    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .25);
    opacity: .7;
    transition: opacity .2s ease, background .2s ease;
    user-select: none;
  }
  .rtmsy .x-risu-rtmsy-fade > summary::-webkit-details-marker { display: none; }
  .rtmsy .x-risu-rtmsy-fade > summary::before { content: "◐"; }
  .rtmsy .x-risu-rtmsy-fade > summary:hover,
  .rtmsy .x-risu-rtmsy-fade[open] > summary { opacity: 1; background: rgba(0, 0, 0, .5); }
  .rtmsy.rtmsy .x-risu-rtmsy-pair.x-risu-rtmsy-pair:has(> .x-risu-rtmsy-fade[open]) :is(.x-risu-rtmsy-pair-char, .x-risu-rtmsy-pair-user) {
    opacity: .08;
    translate: none;
    scale: none;
    filter: none;
  }
}

/* 휴대폰: 메시지마다 위에 두 초상이 마주 봅니다 */
@media (max-width: 900px) {
  .rtmsy.rtmsy { display: grid; }
  .rtmsy {
    --rtmsy-side-w: 6rem;
    grid-template-columns: 1fr 1fr;
    row-gap: .8rem;
    column-gap: .6rem;
    max-width: none;
    padding: var(--rtmsy-pad) 0;
  }
  .rtmsy__side { display: flex; flex-direction: row; align-items: center; gap: .6rem; min-width: 0; }
  .rtmsy__side--char { grid-column: 1; grid-row: 1; justify-content: flex-start; }
  .rtmsy__side--user { grid-column: 2; grid-row: 1; flex-direction: row-reverse; justify-content: flex-start; }
  .rtmsy__frame { position: relative; width: var(--rtmsy-side-w); flex: 0 0 auto; aspect-ratio: 3 / 4; }
  .rtmsy__portrait { width: 100%; height: 100%; border-radius: inherit; }
  .rtmsy__side-name { min-width: 0; color: var(--rtmsy-muted); font-size: .78em; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .rtmsy__main { grid-column: 1 / -1; grid-row: 2; }
  .rtmsy__speaker { display: none; }
  .rtmsy--char .rtmsy__side--char .rtmsy__side-name, .rtmsy--user .rtmsy__side--user .rtmsy__side-name { color: var(--rtmsy-ink); }
  /* 말하는 쪽 초상: 살짝 떠오르고 아래에 옅은 그림자 */
  .rtmsy--char .rtmsy__side--char .rtmsy__frame, .rtmsy--user .rtmsy__side--user .rtmsy__frame {
    translate: 0 -3px;
    scale: 1.04;
    filter: drop-shadow(0 8px 7px rgba(0, 0, 0, .2));
  }
  .rtmsy .x-risu-rtmsy-pair-char, .rtmsy .x-risu-rtmsy-pair-user {
    position: absolute;
    top: var(--rtmsy-pad);
    width: var(--rtmsy-side-w);
    aspect-ratio: 3 / 4;
  }
  .rtmsy--user .x-risu-rtmsy-pair-char { display: block; left: 0; }
  .rtmsy--char .x-risu-rtmsy-pair-user { display: block; right: 0; }
}
.rtmsy { --rtmsy-tilt-char: 0deg; --rtmsy-tilt-user: 0deg; }
.rtmsy__frame { border-radius: .7rem; background: var(--rtmsy-tint); box-shadow: 0 0 0 1px var(--rtmsy-frame), 0 6px 16px var(--rtmsy-shadow); }
.rtmsy .x-risu-rtmsy-pair-char, .rtmsy .x-risu-rtmsy-pair-user { border-radius: .8rem; box-shadow: 0 0 0 1px var(--rtmsy-frame), 0 10px 28px var(--rtmsy-shadow); }
.rtmsy__main {
  padding: 1rem 1.15rem .8rem;
  background: var(--rtmsy-panel);
  border: 1px solid var(--rtmsy-line);
  border-radius: .7rem;
  box-shadow: 0 6px 16px var(--rtmsy-shadow);
}
.rtmsy--user .rtmsy__main { background: var(--rtmsy-panel-user); }
.rtmsy__footer { margin-top: .7rem; padding-top: .5rem; border-top: 1px solid var(--rtmsy-line); font-size: .85em; }

/* ── 배색과 소재: 이 블록만 바꾸면 같은 분류의 다른 변주가 됩니다. (갈색) ── */
.rtmsy {
  --rtmsy-wall: #2a231f;
  --rtmsy-panel: #352c26;
  --rtmsy-panel-user: #3d332c;
  --rtmsy-ink: #ece3d8;
  --rtmsy-muted: #b0a190;
  --rtmsy-accent: #c9a77c;
  --rtmsy-dialog: #e6c9a0;
  --rtmsy-frame: #4b3f36;
  --rtmsy-shadow: rgba(0, 0, 0, .3);
  --rtmsy-line: #4a3d34;
  --rtmsy-tint: #40352e;
  --rtmsy-edit-bg: #2f2722;
}

@import url("https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/variable/pretendardvariable-dynamic-subset.min.css");

/* 바깥 래퍼: 메시지 폭을 확보하고 가운데 정렬합니다. */
.risu-chat > div {
  padding: 0 .75rem;
  margin: auto;
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
}
.risu-chat > div > div {
  width: 100%;
  margin: auto;
  display: flex;
  justify-content: center;
}

/* 글꼴과 크기: 본문 글자 크기는 --rtmsy-font-size로 바꿉니다. */
.rtmsy {
  --rtmsy-bg-fill: transparent;
  --rtmsy-blur: none;
  --rtmsy-bg-edge: none;
  --rtmsy-font-body: "Pretendard Variable", "Pretendard", "Noto Sans KR", -apple-system, "Malgun Gothic", sans-serif;
  --rtmsy-font-display: "Pretendard Variable", "Pretendard", "Noto Sans KR", -apple-system, "Malgun Gothic", sans-serif;
  --rtmsy-font-size: 15.5px;
  --rtmsy-line-height: 1.75;
  --rtmsy-para-gap: .75em;
  --rtmsy-dialog-weight: 600;
}

/* 본문: RisuAI 기본 색·글꼴 변수에 테마 값을 연결합니다. */
.rtmsy {
  --risu-font-family: var(--rtmsy-font-body);
  --FontColorStandard: var(--rtmsy-ink);
  --FontColorBold: var(--rtmsy-ink);
  --FontColorItalic: var(--rtmsy-muted);
  --FontColorItalicBold: var(--rtmsy-muted);
  --FontColorQuote1: var(--rtmsy-muted);
  --FontColorQuote2: var(--rtmsy-dialog);
  position: relative;
  isolation: isolate;
  width: 100%;
  min-width: 0;
  color: var(--rtmsy-ink);
  font-family: var(--rtmsy-font-body);
  font-size: var(--rtmsy-font-size);
  line-height: var(--rtmsy-line-height);
}
.rtmsy, .rtmsy *, .rtmsy *::before, .rtmsy *::after { box-sizing: border-box; }
/* 바깥 래퍼 보정(.risu-chat > div > div)이 테마 루트를 flex로 바꾸지 않게 루트 배치를 고정합니다. */
.rtmsy.rtmsy { display: block; }
.rtmsy__content {
  min-width: 0;
  color: var(--rtmsy-ink);
  word-break: keep-all;
  overflow-wrap: anywhere;
}
.rtmsy__content .chattext {
  --tw-prose-code: var(--rtmsy-ink);
  --tw-prose-pre-code: var(--rtmsy-ink);
  --tw-prose-pre-bg: var(--rtmsy-tint);
  max-width: none;
  color: var(--rtmsy-ink);
  font-size: var(--rtmsy-font-size) !important;
  line-height: var(--rtmsy-line-height) !important;
}
.rtmsy__content :is(p, li, td, th, blockquote) {
  font-size: var(--rtmsy-font-size);
  line-height: var(--rtmsy-line-height);
}
.rtmsy__content p { margin: 0 0 var(--rtmsy-para-gap); }
.rtmsy__content p:last-child { margin-bottom: 0; }
.rtmsy__content :is(h1, h2, h3, h4, h5, h6) {
  --risu-font-family: var(--rtmsy-font-display);
  margin: 1.3em 0 .55em;
  color: var(--rtmsy-ink);
  font-family: var(--rtmsy-font-display);
  line-height: 1.4;
  font-weight: 700;
}
.rtmsy__content h1 { font-size: calc(var(--rtmsy-font-size) * 1.6); }
.rtmsy__content h2 { font-size: calc(var(--rtmsy-font-size) * 1.35); }
.rtmsy__content h3 { font-size: calc(var(--rtmsy-font-size) * 1.15); }
.rtmsy__content :is(h4, h5, h6) { font-size: var(--rtmsy-font-size); }
.rtmsy__content strong { font-weight: 700; }
.rtmsy__content em { color: var(--rtmsy-muted); }
.rtmsy__content mark[risu-mark="quote1"],
.rtmsy__content mark[risu-mark="blockquote1"] { color: var(--rtmsy-muted); background: transparent; }
.rtmsy__content mark[risu-mark="quote2"],
.rtmsy__content mark[risu-mark="blockquote2"] {
  color: var(--rtmsy-dialog);
  font-weight: var(--rtmsy-dialog-weight);
  background: transparent;
}
.rtmsy__content blockquote {
  margin: 1em 0;
  padding: .3em 1em;
  border-left: 3px solid var(--rtmsy-line);
  color: var(--rtmsy-muted);
}
.rtmsy__content :is(ul, ol) { margin: 1em 0; padding-left: 1.5em; }
.rtmsy__content li { margin: .25em 0; color: var(--rtmsy-ink); }
.rtmsy__content li::marker { color: var(--rtmsy-muted); }
.rtmsy__content a { color: var(--rtmsy-accent); text-decoration: underline; }
.rtmsy__content hr { border: 0; border-top: 1px solid var(--rtmsy-line); margin: 1.5em 0; }
.rtmsy__content code {
  --risu-font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  padding: .1em .3em;
  border-radius: .2em;
  color: var(--rtmsy-ink);
  background: var(--rtmsy-tint);
  font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  font-size: calc(var(--rtmsy-font-size) * .88);
}
.rtmsy__content pre {
  max-width: 100%;
  overflow-x: auto;
  padding: .9em 1em;
  color: var(--rtmsy-ink);
  background: var(--rtmsy-tint);
  border-radius: .35rem;
  font-size: calc(var(--rtmsy-font-size) * .88);
  line-height: 1.5;
}
.rtmsy__content pre code { padding: 0; background: transparent; color: inherit; white-space: pre; overflow-wrap: normal; }
.rtmsy__content table {
  display: block;
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
  margin: 1em 0;
}
.rtmsy__content :is(th, td) {
  padding: .5em .7em;
  color: var(--rtmsy-ink);
  border-bottom: 1px solid var(--rtmsy-line);
  text-align: left;
  vertical-align: top;
}
.rtmsy__content th { font-weight: 700; }
.rtmsy__content img { display: block; max-width: 100%; height: auto; margin: .75em auto; }
.rtmsy__content textarea.message-edit-area {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  color: var(--rtmsy-ink) !important;
  background: var(--rtmsy-edit-bg) !important;
  border: 1px solid var(--rtmsy-line);
  border-radius: .4rem;
  font: inherit;
  font-size: var(--rtmsy-font-size) !important;
  line-height: var(--rtmsy-line-height) !important;
}

/* 조작부: 생성 정보와 버튼 */
.rtmsy__footer {
  --risu-theme-textcolor2: var(--rtmsy-muted);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .4rem .75rem;
  min-width: 0;
}
.rtmsy__info, .rtmsy__actions { min-width: 0; max-width: 100%; }
.rtmsy__info > div, .rtmsy__actions > div { flex-wrap: wrap; min-width: 0; gap: .3rem; }
.rtmsy__actions > div > div { flex-wrap: wrap; min-width: 0; }
.rtmsy__footer button {
  background: transparent;
  min-height: 1.9rem;
  padding: .25rem .4rem;
  border-radius: .3rem;
  white-space: normal;
}
.rtmsy__footer button:hover { background: var(--rtmsy-tint); }
.rtmsy :is(a, button, textarea):focus-visible { outline: 2px solid var(--rtmsy-accent); outline-offset: 2px; }

/* 아바타 틀: RisuAI가 넣는 배경 이미지 칸을 틀에 맞춥니다. */
.rtmsy__portrait { overflow: hidden; background: var(--rtmsy-tint); }
.rtmsy__portrait > * {
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  background-size: cover !important;
  background-position: center 22% !important;
  border: 0 !important;
  border-radius: inherit !important;
}

.rtmsy__bg {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background: var(--rtmsy-bg-fill);
  -webkit-backdrop-filter: var(--rtmsy-blur);
  backdrop-filter: var(--rtmsy-blur);
  box-shadow: var(--rtmsy-bg-edge);
}

/* 구조: 메신저 양쪽 */


.rtmsy {
  --rtmsy-col: 44rem;
  --rtmsy-gap: clamp(1rem, 2.5vw, 2rem);
  /* PC 고정 초상: 바깥 가장자리에 붙고, 3:4 비율로 칸 폭과 높이 중 먼저 닿는 쪽까지 커집니다.
     남는 폭은 초상과 본문 사이로, 남는 높이는 위아래로 나뉩니다. */
  --rtmsy-edge: 1rem;
  --rtmsy-fixed-bottom: 5rem; /* 입력창을 피하는 아래 여백 */
  --rtmsy-fixed-w: max(8rem, min(calc((100% - var(--rtmsy-col)) / 2 - var(--rtmsy-gap) - var(--rtmsy-edge)), calc((100vh - var(--rtmsy-edge) - var(--rtmsy-fixed-bottom)) * 3 / 4)));
  --rtmsy-pad: 1rem;
  max-width: var(--rtmsy-col);
  margin: 0 auto;
  padding: .55rem 0;
}
.rtmsy__side { display: none; }
.rtmsy__main { min-width: 0; }
.rtmsy__speaker { margin-bottom: .45rem; color: var(--rtmsy-muted); font-size: .8em; font-weight: 700; letter-spacing: .02em; }
.rtmsy--char .rtmsy__speaker { color: var(--rtmsy-ink); }
/* 정규식이 넣은 조각은 스스로 숨어 있습니다. 이 테마 안에서만 드러냅니다. */
.rtmsy .x-risu-rtmsy-pair { display: block !important; height: 0; margin: 0; padding: 0; }
.rtmsy .x-risu-rtmsy-pair-char, .rtmsy .x-risu-rtmsy-pair-user {
  display: none;
  background-size: cover;
  background-position: center 22%;
}
/* 투명 토글은 PC의 가장 최근 메시지에서만 보입니다. */
.rtmsy .x-risu-rtmsy-fade { display: none; }

/* 고정 초상이 채팅 영역을 기준으로 놓이게 합니다 (이 테마가 채팅에 있을 때만 걸립니다). */
:has(> .default-chat-screen .rtmsy) { transform: translateZ(0); }

/* PC: 가장 최근 메시지 하나에서만 두 초상을 꺼내 채팅 영역 양옆에 고정합니다.
   가장 최근 메시지가 편집 중이라 이미지가 없으면 그 바로 앞 메시지가, 대화가 첫인사뿐이면 첫인사가 맡습니다. */
@media (min-width: 901px) {
  .chat-message-container:first-child .rtmsy :is(.x-risu-rtmsy-pair-char, .x-risu-rtmsy-pair-user),
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy :is(.x-risu-rtmsy-pair-char, .x-risu-rtmsy-pair-user),
  .flex-col-reverse:empty + .risu-chat .rtmsy :is(.x-risu-rtmsy-pair-char, .x-risu-rtmsy-pair-user) {
    display: block;
    position: fixed;
    z-index: 1;
    /* 입력창을 뺀 영역의 세로 가운데: 위아래를 정하고 margin auto로 가운데에 둡니다 (transform을 쓰지 않아야 토글 앵커가 맞습니다) */
    top: var(--rtmsy-edge);
    bottom: var(--rtmsy-fixed-bottom);
    margin-block: auto;
    width: var(--rtmsy-fixed-w);
    aspect-ratio: 3 / 4;
    transition: opacity .3s ease, filter .3s ease, translate .3s ease, scale .3s ease;
  }
  .chat-message-container:first-child .rtmsy .x-risu-rtmsy-pair-char,
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy .x-risu-rtmsy-pair-char,
  .flex-col-reverse:empty + .risu-chat .rtmsy .x-risu-rtmsy-pair-char {
    left: var(--rtmsy-edge);
    transform: rotate(var(--rtmsy-tilt-char));
    anchor-name: --rtmsy-portrait-char;
  }
  .chat-message-container:first-child .rtmsy .x-risu-rtmsy-pair-user,
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy .x-risu-rtmsy-pair-user,
  .flex-col-reverse:empty + .risu-chat .rtmsy .x-risu-rtmsy-pair-user {
    right: var(--rtmsy-edge);
    transform: rotate(var(--rtmsy-tilt-user));
  }
  /* 말하는 쪽: 살짝 떠오르고 아래에 옅은 그림자가 집니다.
     변주마다 쓰는 transform·box-shadow를 덮지 않도록 translate·scale·filter만 씁니다. */
  .chat-message-container:first-child .rtmsy--char .x-risu-rtmsy-pair-char,
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy--char .x-risu-rtmsy-pair-char,
  .flex-col-reverse:empty + .risu-chat .rtmsy--char .x-risu-rtmsy-pair-char,
  .chat-message-container:first-child .rtmsy--user .x-risu-rtmsy-pair-user,
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy--user .x-risu-rtmsy-pair-user,
  .flex-col-reverse:empty + .risu-chat .rtmsy--user .x-risu-rtmsy-pair-user {
    translate: 0 -4px;
    scale: 1.015;
    filter: drop-shadow(0 14px 12px rgba(0, 0, 0, .22));
  }
  /* 투명 토글: 왼쪽 초상 안쪽 왼쪽 위 귀퉁이의 작은 단추. 누르면 두 초상이 거의 투명해져 배경이 보입니다.
     초상 높이는 채팅 영역 폭에 따라 달라 CSS 계산으로는 세로 위치를 맞출 수 없으므로, 앵커 위치 지정으로 초상에 붙입니다.
     앵커를 지원하지 않는 브라우저에서는 채팅 영역 위쪽, 초상과 같은 세로선에 놓입니다. */
  .chat-message-container:first-child .rtmsy .x-risu-rtmsy-fade,
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy .x-risu-rtmsy-fade,
  .flex-col-reverse:empty + .risu-chat .rtmsy .x-risu-rtmsy-fade {
    display: block;
    position: fixed;
    z-index: 2;
    top: calc(var(--rtmsy-edge) + .6rem);
    left: calc(var(--rtmsy-edge) + .6rem);
    margin: 0;
  }
  @supports (anchor-name: --a) {
    .chat-message-container:first-child .rtmsy .x-risu-rtmsy-fade,
    .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy .x-risu-rtmsy-fade,
    .flex-col-reverse:empty + .risu-chat .rtmsy .x-risu-rtmsy-fade {
      position-anchor: --rtmsy-portrait-char;
      top: calc(anchor(top) + .6rem);
      left: calc(anchor(left) + .6rem);
    }
  }
  .rtmsy .x-risu-rtmsy-fade > summary {
    display: grid;
    place-items: center;
    width: 1.9rem;
    height: 1.9rem;
    border-radius: 50%;
    list-style: none;
    cursor: pointer;
    color: #fff;
    font-size: .95rem;
    line-height: 1;
    background: rgba(0, 0, 0, .32);
    -webkit-backdrop-filter: blur(6px);
    backdrop-filter: blur(6px);
    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .25);
    opacity: .7;
    transition: opacity .2s ease, background .2s ease;
    user-select: none;
  }
  .rtmsy .x-risu-rtmsy-fade > summary::-webkit-details-marker { display: none; }
  .rtmsy .x-risu-rtmsy-fade > summary::before { content: "◐"; }
  .rtmsy .x-risu-rtmsy-fade > summary:hover,
  .rtmsy .x-risu-rtmsy-fade[open] > summary { opacity: 1; background: rgba(0, 0, 0, .5); }
  .rtmsy.rtmsy .x-risu-rtmsy-pair.x-risu-rtmsy-pair:has(> .x-risu-rtmsy-fade[open]) :is(.x-risu-rtmsy-pair-char, .x-risu-rtmsy-pair-user) {
    opacity: .08;
    translate: none;
    scale: none;
    filter: none;
  }
}

/* 휴대폰: 메시지마다 위에 두 초상이 마주 봅니다 */
@media (max-width: 900px) {
  .rtmsy.rtmsy { display: grid; }
  .rtmsy {
    --rtmsy-side-w: 6rem;
    grid-template-columns: 1fr 1fr;
    row-gap: .8rem;
    column-gap: .6rem;
    max-width: none;
    padding: var(--rtmsy-pad) 0;
  }
  .rtmsy__side { display: flex; flex-direction: row; align-items: center; gap: .6rem; min-width: 0; }
  .rtmsy__side--char { grid-column: 1; grid-row: 1; justify-content: flex-start; }
  .rtmsy__side--user { grid-column: 2; grid-row: 1; flex-direction: row-reverse; justify-content: flex-start; }
  .rtmsy__frame { position: relative; width: var(--rtmsy-side-w); flex: 0 0 auto; aspect-ratio: 3 / 4; }
  .rtmsy__portrait { width: 100%; height: 100%; border-radius: inherit; }
  .rtmsy__side-name { min-width: 0; color: var(--rtmsy-muted); font-size: .78em; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .rtmsy__main { grid-column: 1 / -1; grid-row: 2; }
  .rtmsy__speaker { display: none; }
  .rtmsy--char .rtmsy__side--char .rtmsy__side-name, .rtmsy--user .rtmsy__side--user .rtmsy__side-name { color: var(--rtmsy-ink); }
  /* 말하는 쪽 초상: 살짝 떠오르고 아래에 옅은 그림자 */
  .rtmsy--char .rtmsy__side--char .rtmsy__frame, .rtmsy--user .rtmsy__side--user .rtmsy__frame {
    translate: 0 -3px;
    scale: 1.04;
    filter: drop-shadow(0 8px 7px rgba(0, 0, 0, .2));
  }
  .rtmsy .x-risu-rtmsy-pair-char, .rtmsy .x-risu-rtmsy-pair-user {
    position: absolute;
    top: var(--rtmsy-pad);
    width: var(--rtmsy-side-w);
    aspect-ratio: 3 / 4;
  }
  .rtmsy--user .x-risu-rtmsy-pair-char { display: block; left: 0; }
  .rtmsy--char .x-risu-rtmsy-pair-user { display: block; right: 0; }
}
.rtmsy { --rtmsy-tilt-char: 0deg; --rtmsy-tilt-user: 0deg; }
.rtmsy__frame { border-radius: .7rem; background: var(--rtmsy-tint); box-shadow: 0 0 0 1px var(--rtmsy-frame), 0 6px 16px var(--rtmsy-shadow); }
.rtmsy .x-risu-rtmsy-pair-char, .rtmsy .x-risu-rtmsy-pair-user { border-radius: .8rem; box-shadow: 0 0 0 1px var(--rtmsy-frame), 0 10px 28px var(--rtmsy-shadow); }
.rtmsy__main {
  padding: 1rem 1.15rem .8rem;
  background: var(--rtmsy-panel);
  border: 1px solid var(--rtmsy-line);
  border-radius: .7rem;
  box-shadow: 0 6px 16px var(--rtmsy-shadow);
}
.rtmsy--user .rtmsy__main { background: var(--rtmsy-panel-user); }
.rtmsy__footer { margin-top: .7rem; padding-top: .5rem; border-top: 1px solid var(--rtmsy-line); font-size: .85em; }

/* ── 배색과 소재: 이 블록만 바꾸면 같은 분류의 다른 변주가 됩니다. (남색) ── */
.rtmsy {
  --rtmsy-wall: #161c29;
  --rtmsy-panel: #1e2636;
  --rtmsy-panel-user: #242d40;
  --rtmsy-ink: #e3e6ec;
  --rtmsy-muted: #98a1b2;
  --rtmsy-accent: #c2a86e;
  --rtmsy-dialog: #e2cf9e;
  --rtmsy-frame: #2d3750;
  --rtmsy-shadow: rgba(0, 0, 0, .35);
  --rtmsy-line: #2c3650;
  --rtmsy-tint: #283149;
  --rtmsy-edit-bg: #1a2130;
}

@import url("https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/variable/pretendardvariable-dynamic-subset.min.css");

/* 바깥 래퍼: 메시지 폭을 확보하고 가운데 정렬합니다. */
.risu-chat > div {
  padding: 0 .75rem;
  margin: auto;
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
}
.risu-chat > div > div {
  width: 100%;
  margin: auto;
  display: flex;
  justify-content: center;
}

/* 글꼴과 크기: 본문 글자 크기는 --rtmsy-font-size로 바꿉니다. */
.rtmsy {
  --rtmsy-bg-fill: transparent;
  --rtmsy-blur: none;
  --rtmsy-bg-edge: none;
  --rtmsy-font-body: "Pretendard Variable", "Pretendard", "Noto Sans KR", -apple-system, "Malgun Gothic", sans-serif;
  --rtmsy-font-display: "Pretendard Variable", "Pretendard", "Noto Sans KR", -apple-system, "Malgun Gothic", sans-serif;
  --rtmsy-font-size: 15.5px;
  --rtmsy-line-height: 1.75;
  --rtmsy-para-gap: .75em;
  --rtmsy-dialog-weight: 600;
}

/* 본문: RisuAI 기본 색·글꼴 변수에 테마 값을 연결합니다. */
.rtmsy {
  --risu-font-family: var(--rtmsy-font-body);
  --FontColorStandard: var(--rtmsy-ink);
  --FontColorBold: var(--rtmsy-ink);
  --FontColorItalic: var(--rtmsy-muted);
  --FontColorItalicBold: var(--rtmsy-muted);
  --FontColorQuote1: var(--rtmsy-muted);
  --FontColorQuote2: var(--rtmsy-dialog);
  position: relative;
  isolation: isolate;
  width: 100%;
  min-width: 0;
  color: var(--rtmsy-ink);
  font-family: var(--rtmsy-font-body);
  font-size: var(--rtmsy-font-size);
  line-height: var(--rtmsy-line-height);
}
.rtmsy, .rtmsy *, .rtmsy *::before, .rtmsy *::after { box-sizing: border-box; }
/* 바깥 래퍼 보정(.risu-chat > div > div)이 테마 루트를 flex로 바꾸지 않게 루트 배치를 고정합니다. */
.rtmsy.rtmsy { display: block; }
.rtmsy__content {
  min-width: 0;
  color: var(--rtmsy-ink);
  word-break: keep-all;
  overflow-wrap: anywhere;
}
.rtmsy__content .chattext {
  --tw-prose-code: var(--rtmsy-ink);
  --tw-prose-pre-code: var(--rtmsy-ink);
  --tw-prose-pre-bg: var(--rtmsy-tint);
  max-width: none;
  color: var(--rtmsy-ink);
  font-size: var(--rtmsy-font-size) !important;
  line-height: var(--rtmsy-line-height) !important;
}
.rtmsy__content :is(p, li, td, th, blockquote) {
  font-size: var(--rtmsy-font-size);
  line-height: var(--rtmsy-line-height);
}
.rtmsy__content p { margin: 0 0 var(--rtmsy-para-gap); }
.rtmsy__content p:last-child { margin-bottom: 0; }
.rtmsy__content :is(h1, h2, h3, h4, h5, h6) {
  --risu-font-family: var(--rtmsy-font-display);
  margin: 1.3em 0 .55em;
  color: var(--rtmsy-ink);
  font-family: var(--rtmsy-font-display);
  line-height: 1.4;
  font-weight: 700;
}
.rtmsy__content h1 { font-size: calc(var(--rtmsy-font-size) * 1.6); }
.rtmsy__content h2 { font-size: calc(var(--rtmsy-font-size) * 1.35); }
.rtmsy__content h3 { font-size: calc(var(--rtmsy-font-size) * 1.15); }
.rtmsy__content :is(h4, h5, h6) { font-size: var(--rtmsy-font-size); }
.rtmsy__content strong { font-weight: 700; }
.rtmsy__content em { color: var(--rtmsy-muted); }
.rtmsy__content mark[risu-mark="quote1"],
.rtmsy__content mark[risu-mark="blockquote1"] { color: var(--rtmsy-muted); background: transparent; }
.rtmsy__content mark[risu-mark="quote2"],
.rtmsy__content mark[risu-mark="blockquote2"] {
  color: var(--rtmsy-dialog);
  font-weight: var(--rtmsy-dialog-weight);
  background: transparent;
}
.rtmsy__content blockquote {
  margin: 1em 0;
  padding: .3em 1em;
  border-left: 3px solid var(--rtmsy-line);
  color: var(--rtmsy-muted);
}
.rtmsy__content :is(ul, ol) { margin: 1em 0; padding-left: 1.5em; }
.rtmsy__content li { margin: .25em 0; color: var(--rtmsy-ink); }
.rtmsy__content li::marker { color: var(--rtmsy-muted); }
.rtmsy__content a { color: var(--rtmsy-accent); text-decoration: underline; }
.rtmsy__content hr { border: 0; border-top: 1px solid var(--rtmsy-line); margin: 1.5em 0; }
.rtmsy__content code {
  --risu-font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  padding: .1em .3em;
  border-radius: .2em;
  color: var(--rtmsy-ink);
  background: var(--rtmsy-tint);
  font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  font-size: calc(var(--rtmsy-font-size) * .88);
}
.rtmsy__content pre {
  max-width: 100%;
  overflow-x: auto;
  padding: .9em 1em;
  color: var(--rtmsy-ink);
  background: var(--rtmsy-tint);
  border-radius: .35rem;
  font-size: calc(var(--rtmsy-font-size) * .88);
  line-height: 1.5;
}
.rtmsy__content pre code { padding: 0; background: transparent; color: inherit; white-space: pre; overflow-wrap: normal; }
.rtmsy__content table {
  display: block;
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
  margin: 1em 0;
}
.rtmsy__content :is(th, td) {
  padding: .5em .7em;
  color: var(--rtmsy-ink);
  border-bottom: 1px solid var(--rtmsy-line);
  text-align: left;
  vertical-align: top;
}
.rtmsy__content th { font-weight: 700; }
.rtmsy__content img { display: block; max-width: 100%; height: auto; margin: .75em auto; }
.rtmsy__content textarea.message-edit-area {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  color: var(--rtmsy-ink) !important;
  background: var(--rtmsy-edit-bg) !important;
  border: 1px solid var(--rtmsy-line);
  border-radius: .4rem;
  font: inherit;
  font-size: var(--rtmsy-font-size) !important;
  line-height: var(--rtmsy-line-height) !important;
}

/* 조작부: 생성 정보와 버튼 */
.rtmsy__footer {
  --risu-theme-textcolor2: var(--rtmsy-muted);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .4rem .75rem;
  min-width: 0;
}
.rtmsy__info, .rtmsy__actions { min-width: 0; max-width: 100%; }
.rtmsy__info > div, .rtmsy__actions > div { flex-wrap: wrap; min-width: 0; gap: .3rem; }
.rtmsy__actions > div > div { flex-wrap: wrap; min-width: 0; }
.rtmsy__footer button {
  background: transparent;
  min-height: 1.9rem;
  padding: .25rem .4rem;
  border-radius: .3rem;
  white-space: normal;
}
.rtmsy__footer button:hover { background: var(--rtmsy-tint); }
.rtmsy :is(a, button, textarea):focus-visible { outline: 2px solid var(--rtmsy-accent); outline-offset: 2px; }

/* 아바타 틀: RisuAI가 넣는 배경 이미지 칸을 틀에 맞춥니다. */
.rtmsy__portrait { overflow: hidden; background: var(--rtmsy-tint); }
.rtmsy__portrait > * {
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  background-size: cover !important;
  background-position: center 22% !important;
  border: 0 !important;
  border-radius: inherit !important;
}

.rtmsy__bg {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background: var(--rtmsy-bg-fill);
  -webkit-backdrop-filter: var(--rtmsy-blur);
  backdrop-filter: var(--rtmsy-blur);
  box-shadow: var(--rtmsy-bg-edge);
}

/* 구조: 메신저 양쪽 */


.rtmsy {
  --rtmsy-col: 44rem;
  --rtmsy-gap: clamp(1rem, 2.5vw, 2rem);
  /* PC 고정 초상: 바깥 가장자리에 붙고, 3:4 비율로 칸 폭과 높이 중 먼저 닿는 쪽까지 커집니다.
     남는 폭은 초상과 본문 사이로, 남는 높이는 위아래로 나뉩니다. */
  --rtmsy-edge: 1rem;
  --rtmsy-fixed-bottom: 5rem; /* 입력창을 피하는 아래 여백 */
  --rtmsy-fixed-w: max(8rem, min(calc((100% - var(--rtmsy-col)) / 2 - var(--rtmsy-gap) - var(--rtmsy-edge)), calc((100vh - var(--rtmsy-edge) - var(--rtmsy-fixed-bottom)) * 3 / 4)));
  --rtmsy-pad: 1rem;
  max-width: var(--rtmsy-col);
  margin: 0 auto;
  padding: .55rem 0;
}
.rtmsy__side { display: none; }
.rtmsy__main { min-width: 0; }
.rtmsy__speaker { margin-bottom: .45rem; color: var(--rtmsy-muted); font-size: .8em; font-weight: 700; letter-spacing: .02em; }
.rtmsy--char .rtmsy__speaker { color: var(--rtmsy-ink); }
/* 정규식이 넣은 조각은 스스로 숨어 있습니다. 이 테마 안에서만 드러냅니다. */
.rtmsy .x-risu-rtmsy-pair { display: block !important; height: 0; margin: 0; padding: 0; }
.rtmsy .x-risu-rtmsy-pair-char, .rtmsy .x-risu-rtmsy-pair-user {
  display: none;
  background-size: cover;
  background-position: center 22%;
}
/* 투명 토글은 PC의 가장 최근 메시지에서만 보입니다. */
.rtmsy .x-risu-rtmsy-fade { display: none; }

/* 고정 초상이 채팅 영역을 기준으로 놓이게 합니다 (이 테마가 채팅에 있을 때만 걸립니다). */
:has(> .default-chat-screen .rtmsy) { transform: translateZ(0); }

/* PC: 가장 최근 메시지 하나에서만 두 초상을 꺼내 채팅 영역 양옆에 고정합니다.
   가장 최근 메시지가 편집 중이라 이미지가 없으면 그 바로 앞 메시지가, 대화가 첫인사뿐이면 첫인사가 맡습니다. */
@media (min-width: 901px) {
  .chat-message-container:first-child .rtmsy :is(.x-risu-rtmsy-pair-char, .x-risu-rtmsy-pair-user),
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy :is(.x-risu-rtmsy-pair-char, .x-risu-rtmsy-pair-user),
  .flex-col-reverse:empty + .risu-chat .rtmsy :is(.x-risu-rtmsy-pair-char, .x-risu-rtmsy-pair-user) {
    display: block;
    position: fixed;
    z-index: 1;
    /* 입력창을 뺀 영역의 세로 가운데: 위아래를 정하고 margin auto로 가운데에 둡니다 (transform을 쓰지 않아야 토글 앵커가 맞습니다) */
    top: var(--rtmsy-edge);
    bottom: var(--rtmsy-fixed-bottom);
    margin-block: auto;
    width: var(--rtmsy-fixed-w);
    aspect-ratio: 3 / 4;
    transition: opacity .3s ease, filter .3s ease, translate .3s ease, scale .3s ease;
  }
  .chat-message-container:first-child .rtmsy .x-risu-rtmsy-pair-char,
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy .x-risu-rtmsy-pair-char,
  .flex-col-reverse:empty + .risu-chat .rtmsy .x-risu-rtmsy-pair-char {
    left: var(--rtmsy-edge);
    transform: rotate(var(--rtmsy-tilt-char));
    anchor-name: --rtmsy-portrait-char;
  }
  .chat-message-container:first-child .rtmsy .x-risu-rtmsy-pair-user,
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy .x-risu-rtmsy-pair-user,
  .flex-col-reverse:empty + .risu-chat .rtmsy .x-risu-rtmsy-pair-user {
    right: var(--rtmsy-edge);
    transform: rotate(var(--rtmsy-tilt-user));
  }
  /* 말하는 쪽: 살짝 떠오르고 아래에 옅은 그림자가 집니다.
     변주마다 쓰는 transform·box-shadow를 덮지 않도록 translate·scale·filter만 씁니다. */
  .chat-message-container:first-child .rtmsy--char .x-risu-rtmsy-pair-char,
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy--char .x-risu-rtmsy-pair-char,
  .flex-col-reverse:empty + .risu-chat .rtmsy--char .x-risu-rtmsy-pair-char,
  .chat-message-container:first-child .rtmsy--user .x-risu-rtmsy-pair-user,
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy--user .x-risu-rtmsy-pair-user,
  .flex-col-reverse:empty + .risu-chat .rtmsy--user .x-risu-rtmsy-pair-user {
    translate: 0 -4px;
    scale: 1.015;
    filter: drop-shadow(0 14px 12px rgba(0, 0, 0, .22));
  }
  /* 투명 토글: 왼쪽 초상 안쪽 왼쪽 위 귀퉁이의 작은 단추. 누르면 두 초상이 거의 투명해져 배경이 보입니다.
     초상 높이는 채팅 영역 폭에 따라 달라 CSS 계산으로는 세로 위치를 맞출 수 없으므로, 앵커 위치 지정으로 초상에 붙입니다.
     앵커를 지원하지 않는 브라우저에서는 채팅 영역 위쪽, 초상과 같은 세로선에 놓입니다. */
  .chat-message-container:first-child .rtmsy .x-risu-rtmsy-fade,
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy .x-risu-rtmsy-fade,
  .flex-col-reverse:empty + .risu-chat .rtmsy .x-risu-rtmsy-fade {
    display: block;
    position: fixed;
    z-index: 2;
    top: calc(var(--rtmsy-edge) + .6rem);
    left: calc(var(--rtmsy-edge) + .6rem);
    margin: 0;
  }
  @supports (anchor-name: --a) {
    .chat-message-container:first-child .rtmsy .x-risu-rtmsy-fade,
    .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy .x-risu-rtmsy-fade,
    .flex-col-reverse:empty + .risu-chat .rtmsy .x-risu-rtmsy-fade {
      position-anchor: --rtmsy-portrait-char;
      top: calc(anchor(top) + .6rem);
      left: calc(anchor(left) + .6rem);
    }
  }
  .rtmsy .x-risu-rtmsy-fade > summary {
    display: grid;
    place-items: center;
    width: 1.9rem;
    height: 1.9rem;
    border-radius: 50%;
    list-style: none;
    cursor: pointer;
    color: #fff;
    font-size: .95rem;
    line-height: 1;
    background: rgba(0, 0, 0, .32);
    -webkit-backdrop-filter: blur(6px);
    backdrop-filter: blur(6px);
    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .25);
    opacity: .7;
    transition: opacity .2s ease, background .2s ease;
    user-select: none;
  }
  .rtmsy .x-risu-rtmsy-fade > summary::-webkit-details-marker { display: none; }
  .rtmsy .x-risu-rtmsy-fade > summary::before { content: "◐"; }
  .rtmsy .x-risu-rtmsy-fade > summary:hover,
  .rtmsy .x-risu-rtmsy-fade[open] > summary { opacity: 1; background: rgba(0, 0, 0, .5); }
  .rtmsy.rtmsy .x-risu-rtmsy-pair.x-risu-rtmsy-pair:has(> .x-risu-rtmsy-fade[open]) :is(.x-risu-rtmsy-pair-char, .x-risu-rtmsy-pair-user) {
    opacity: .08;
    translate: none;
    scale: none;
    filter: none;
  }
}

/* 휴대폰: 메시지마다 위에 두 초상이 마주 봅니다 */
@media (max-width: 900px) {
  .rtmsy.rtmsy { display: grid; }
  .rtmsy {
    --rtmsy-side-w: 6rem;
    grid-template-columns: 1fr 1fr;
    row-gap: .8rem;
    column-gap: .6rem;
    max-width: none;
    padding: var(--rtmsy-pad) 0;
  }
  .rtmsy__side { display: flex; flex-direction: row; align-items: center; gap: .6rem; min-width: 0; }
  .rtmsy__side--char { grid-column: 1; grid-row: 1; justify-content: flex-start; }
  .rtmsy__side--user { grid-column: 2; grid-row: 1; flex-direction: row-reverse; justify-content: flex-start; }
  .rtmsy__frame { position: relative; width: var(--rtmsy-side-w); flex: 0 0 auto; aspect-ratio: 3 / 4; }
  .rtmsy__portrait { width: 100%; height: 100%; border-radius: inherit; }
  .rtmsy__side-name { min-width: 0; color: var(--rtmsy-muted); font-size: .78em; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .rtmsy__main { grid-column: 1 / -1; grid-row: 2; }
  .rtmsy__speaker { display: none; }
  .rtmsy--char .rtmsy__side--char .rtmsy__side-name, .rtmsy--user .rtmsy__side--user .rtmsy__side-name { color: var(--rtmsy-ink); }
  /* 말하는 쪽 초상: 살짝 떠오르고 아래에 옅은 그림자 */
  .rtmsy--char .rtmsy__side--char .rtmsy__frame, .rtmsy--user .rtmsy__side--user .rtmsy__frame {
    translate: 0 -3px;
    scale: 1.04;
    filter: drop-shadow(0 8px 7px rgba(0, 0, 0, .2));
  }
  .rtmsy .x-risu-rtmsy-pair-char, .rtmsy .x-risu-rtmsy-pair-user {
    position: absolute;
    top: var(--rtmsy-pad);
    width: var(--rtmsy-side-w);
    aspect-ratio: 3 / 4;
  }
  .rtmsy--user .x-risu-rtmsy-pair-char { display: block; left: 0; }
  .rtmsy--char .x-risu-rtmsy-pair-user { display: block; right: 0; }
}
.rtmsy { --rtmsy-tilt-char: 0deg; --rtmsy-tilt-user: 0deg; }
.rtmsy__frame { border-radius: .7rem; background: var(--rtmsy-tint); box-shadow: 0 0 0 1px var(--rtmsy-frame), 0 6px 16px var(--rtmsy-shadow); }
.rtmsy .x-risu-rtmsy-pair-char, .rtmsy .x-risu-rtmsy-pair-user { border-radius: .8rem; box-shadow: 0 0 0 1px var(--rtmsy-frame), 0 10px 28px var(--rtmsy-shadow); }
.rtmsy__main {
  padding: 1rem 1.15rem .8rem;
  background: var(--rtmsy-panel);
  border: 1px solid var(--rtmsy-line);
  border-radius: .7rem;
  box-shadow: 0 6px 16px var(--rtmsy-shadow);
}
.rtmsy--user .rtmsy__main { background: var(--rtmsy-panel-user); }
.rtmsy__footer { margin-top: .7rem; padding-top: .5rem; border-top: 1px solid var(--rtmsy-line); font-size: .85em; }

/* ── 배색과 소재: 이 블록만 바꾸면 같은 분류의 다른 변주가 됩니다. (글래스) ── */
.rtmsy {
  --rtmsy-blur: blur(16px) saturate(1.25);
  --rtmsy-bg-edge: inset 0 0 0 1px rgba(255, 255, 255, .13), inset 0 1px 0 rgba(255, 255, 255, .18);
  --rtmsy-bg-fill: linear-gradient(160deg, rgba(255, 255, 255, .07), rgba(255, 255, 255, .015) 65%);
  --rtmsy-wall: transparent;
  --rtmsy-panel: rgba(16, 18, 24, .42);
  --rtmsy-panel-user: rgba(30, 32, 40, .42);
  --rtmsy-ink: #eef0f4;
  --rtmsy-muted: rgba(228, 230, 236, .66);
  --rtmsy-accent: #e3cfae;
  --rtmsy-dialog: #ffffff;
  --rtmsy-frame: rgba(255, 255, 255, .16);
  --rtmsy-shadow: rgba(0, 0, 0, .25);
  --rtmsy-line: rgba(255, 255, 255, .13);
  --rtmsy-tint: rgba(255, 255, 255, .07);
  --rtmsy-edit-bg: rgba(10, 11, 15, .5);
}

@import url("https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/variable/pretendardvariable-dynamic-subset.min.css");

/* 바깥 래퍼: 메시지 폭을 확보하고 가운데 정렬합니다. */
.risu-chat > div {
  padding: 0;
  margin: auto;
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
}
.risu-chat > div > div {
  width: 100%;
  margin: auto;
  display: flex;
  justify-content: center;
}

/* 글꼴과 크기: 본문 글자 크기는 --rtmsa-font-size로 바꿉니다. */
.rtmsa {
  --rtmsa-bg-fill: transparent;
  --rtmsa-blur: none;
  --rtmsa-bg-edge: none;
  --rtmsa-font-body: "Pretendard Variable", "Pretendard", "Noto Sans KR", -apple-system, "Malgun Gothic", sans-serif;
  --rtmsa-font-display: "Pretendard Variable", "Pretendard", "Noto Sans KR", -apple-system, "Malgun Gothic", sans-serif;
  --rtmsa-font-size: 15.5px;
  --rtmsa-line-height: 1.7;
  --rtmsa-para-gap: .7em;
  --rtmsa-dialog-weight: 600;
  --rtmsa-avatar: clamp(2.6rem, 6vw, 3.2rem);
}

/* 본문: RisuAI 기본 색·글꼴 변수에 테마 값을 연결합니다. */
.rtmsa {
  --risu-font-family: var(--rtmsa-font-body);
  --FontColorStandard: var(--rtmsa-ink);
  --FontColorBold: var(--rtmsa-ink);
  --FontColorItalic: var(--rtmsa-muted);
  --FontColorItalicBold: var(--rtmsa-muted);
  --FontColorQuote1: var(--rtmsa-muted);
  --FontColorQuote2: var(--rtmsa-dialog);
  position: relative;
  isolation: isolate;
  width: 100%;
  min-width: 0;
  color: var(--rtmsa-ink);
  font-family: var(--rtmsa-font-body);
  font-size: var(--rtmsa-font-size);
  line-height: var(--rtmsa-line-height);
}
.rtmsa, .rtmsa *, .rtmsa *::before, .rtmsa *::after { box-sizing: border-box; }
/* 바깥 래퍼 보정(.risu-chat > div > div)이 테마 루트를 flex로 바꾸지 않게 루트 배치를 고정합니다. */
.rtmsa.rtmsa { display: block; }
.rtmsa__content {
  min-width: 0;
  color: var(--rtmsa-ink);
  word-break: keep-all;
  overflow-wrap: anywhere;
}
.rtmsa__content .chattext {
  --tw-prose-code: var(--rtmsa-ink);
  --tw-prose-pre-code: var(--rtmsa-ink);
  --tw-prose-pre-bg: var(--rtmsa-tint);
  max-width: none;
  color: var(--rtmsa-ink);
  font-size: var(--rtmsa-font-size) !important;
  line-height: var(--rtmsa-line-height) !important;
}
.rtmsa__content :is(p, li, td, th, blockquote) {
  font-size: var(--rtmsa-font-size);
  line-height: var(--rtmsa-line-height);
}
.rtmsa__content p { margin: 0 0 var(--rtmsa-para-gap); }
.rtmsa__content p:last-child { margin-bottom: 0; }
.rtmsa__content :is(h1, h2, h3, h4, h5, h6) {
  --risu-font-family: var(--rtmsa-font-display);
  margin: 1.3em 0 .55em;
  color: var(--rtmsa-ink);
  font-family: var(--rtmsa-font-display);
  line-height: 1.4;
  font-weight: 700;
}
.rtmsa__content h1 { font-size: calc(var(--rtmsa-font-size) * 1.6); }
.rtmsa__content h2 { font-size: calc(var(--rtmsa-font-size) * 1.35); }
