  margin: 1.3em 0 .55em;
  color: var(--rtlty-ink);
  font-family: var(--rtlty-font-display);
  line-height: 1.4;
  font-weight: 700;
}
.rtlty__content h1 { font-size: calc(var(--rtlty-font-size) * 1.6); }
.rtlty__content h2 { font-size: calc(var(--rtlty-font-size) * 1.35); }
.rtlty__content h3 { font-size: calc(var(--rtlty-font-size) * 1.15); }
.rtlty__content :is(h4, h5, h6) { font-size: var(--rtlty-font-size); }
.rtlty__content strong { font-weight: 700; }
.rtlty__content em { color: var(--rtlty-muted); }
.rtlty__content mark[risu-mark="quote1"],
.rtlty__content mark[risu-mark="blockquote1"] { color: var(--rtlty-muted); background: transparent; }
.rtlty__content mark[risu-mark="quote2"],
.rtlty__content mark[risu-mark="blockquote2"] {
  color: var(--rtlty-dialog);
  font-weight: var(--rtlty-dialog-weight);
  background: transparent;
}
.rtlty__content blockquote {
  margin: 1em 0;
  padding: .3em 1em;
  border-left: 3px solid var(--rtlty-line);
  color: var(--rtlty-muted);
}
.rtlty__content :is(ul, ol) { margin: 1em 0; padding-left: 1.5em; }
.rtlty__content li { margin: .25em 0; color: var(--rtlty-ink); }
.rtlty__content li::marker { color: var(--rtlty-muted); }
.rtlty__content a { color: var(--rtlty-accent); text-decoration: underline; }
.rtlty__content hr { border: 0; border-top: 1px solid var(--rtlty-line); margin: 1.5em 0; }
.rtlty__content code {
  --risu-font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  padding: .1em .3em;
  border-radius: .2em;
  color: var(--rtlty-ink);
  background: var(--rtlty-tint);
  font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  font-size: calc(var(--rtlty-font-size) * .88);
}
.rtlty__content pre {
  max-width: 100%;
  overflow-x: auto;
  padding: .9em 1em;
  color: var(--rtlty-ink);
  background: var(--rtlty-tint);
  border-radius: .35rem;
  font-size: calc(var(--rtlty-font-size) * .88);
  line-height: 1.5;
}
.rtlty__content pre code { padding: 0; background: transparent; color: inherit; white-space: pre; overflow-wrap: normal; }
.rtlty__content table {
  display: block;
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
  margin: 1em 0;
}
.rtlty__content :is(th, td) {
  padding: .5em .7em;
  color: var(--rtlty-ink);
  border-bottom: 1px solid var(--rtlty-line);
  text-align: left;
  vertical-align: top;
}
.rtlty__content th { font-weight: 700; }
.rtlty__content img { display: block; max-width: 100%; height: auto; margin: .75em auto; }
.rtlty__content textarea.message-edit-area {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  color: var(--rtlty-ink) !important;
  background: var(--rtlty-edit-bg) !important;
  border: 1px solid var(--rtlty-line);
  border-radius: .4rem;
  font: inherit;
  font-size: var(--rtlty-font-size) !important;
  line-height: var(--rtlty-line-height) !important;
}

/* 조작부: 생성 정보와 버튼 */
.rtlty__footer {
  --risu-theme-textcolor2: var(--rtlty-muted);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .4rem .75rem;
  min-width: 0;
}
.rtlty__info, .rtlty__actions { min-width: 0; max-width: 100%; }
.rtlty__info > div, .rtlty__actions > div { flex-wrap: wrap; min-width: 0; gap: .3rem; }
.rtlty__actions > div > div { flex-wrap: wrap; min-width: 0; }
.rtlty__footer button {
  background: transparent;
  min-height: 1.9rem;
  padding: .25rem .4rem;
  border-radius: .3rem;
  white-space: normal;
}
.rtlty__footer button:hover { background: var(--rtlty-tint); }
.rtlty :is(a, button, textarea):focus-visible { outline: 2px solid var(--rtlty-accent); outline-offset: 2px; }

/* 아바타 틀: RisuAI가 넣는 배경 이미지 칸을 틀에 맞춥니다. */
.rtlty__portrait { overflow: hidden; background: var(--rtlty-tint); }
.rtlty__portrait > * {
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  background-size: cover !important;
  background-position: center 22% !important;
  border: 0 !important;
  border-radius: inherit !important;
}

.rtlty__bg {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background: var(--rtlty-bg-fill);
  -webkit-backdrop-filter: var(--rtlty-blur);
  backdrop-filter: var(--rtlty-blur);
  box-shadow: var(--rtlty-bg-edge);
}

/* 구조: 편지 양쪽 */


.rtlty {
  --rtlty-col: 44rem;
  --rtlty-gap: clamp(1rem, 2.5vw, 2rem);
  /* PC 고정 초상: 바깥 가장자리에 붙고, 3:4 비율로 칸 폭과 높이 중 먼저 닿는 쪽까지 커집니다.
     남는 폭은 초상과 본문 사이로, 남는 높이는 위아래로 나뉩니다. */
  --rtlty-edge: 1rem;
  --rtlty-fixed-bottom: 5rem; /* 입력창을 피하는 아래 여백 */
  --rtlty-fixed-w: max(8rem, min(calc((100% - var(--rtlty-col)) / 2 - var(--rtlty-gap) - var(--rtlty-edge)), calc((100vh - var(--rtlty-edge) - var(--rtlty-fixed-bottom)) * 3 / 4)));
  --rtlty-pad: 1rem;
  max-width: var(--rtlty-col);
  margin: 0 auto;
  padding: .55rem 0;
}
.rtlty__side { display: none; }
.rtlty__main { min-width: 0; }
.rtlty__speaker { margin-bottom: .45rem; color: var(--rtlty-muted); font-size: .8em; font-weight: 700; letter-spacing: .02em; }
.rtlty--char .rtlty__speaker { color: var(--rtlty-ink); }
/* 정규식이 넣은 조각은 스스로 숨어 있습니다. 이 테마 안에서만 드러냅니다. */
.rtlty .x-risu-rtlty-pair { display: block !important; height: 0; margin: 0; padding: 0; }
.rtlty .x-risu-rtlty-pair-char, .rtlty .x-risu-rtlty-pair-user {
  display: none;
  background-size: cover;
  background-position: center 22%;
}
/* 투명 토글은 PC의 가장 최근 메시지에서만 보입니다. */
.rtlty .x-risu-rtlty-fade { display: none; }

/* 고정 초상이 채팅 영역을 기준으로 놓이게 합니다 (이 테마가 채팅에 있을 때만 걸립니다). */
:has(> .default-chat-screen .rtlty) { transform: translateZ(0); }

/* PC: 가장 최근 메시지 하나에서만 두 초상을 꺼내 채팅 영역 양옆에 고정합니다.
   가장 최근 메시지가 편집 중이라 이미지가 없으면 그 바로 앞 메시지가, 대화가 첫인사뿐이면 첫인사가 맡습니다. */
@media (min-width: 901px) {
  .chat-message-container:first-child .rtlty :is(.x-risu-rtlty-pair-char, .x-risu-rtlty-pair-user),
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty :is(.x-risu-rtlty-pair-char, .x-risu-rtlty-pair-user),
  .flex-col-reverse:empty + .risu-chat .rtlty :is(.x-risu-rtlty-pair-char, .x-risu-rtlty-pair-user) {
    display: block;
    position: fixed;
    z-index: 1;
    /* 입력창을 뺀 영역의 세로 가운데: 위아래를 정하고 margin auto로 가운데에 둡니다 (transform을 쓰지 않아야 토글 앵커가 맞습니다) */
    top: var(--rtlty-edge);
    bottom: var(--rtlty-fixed-bottom);
    margin-block: auto;
    width: var(--rtlty-fixed-w);
    aspect-ratio: 3 / 4;
    transition: opacity .3s ease, filter .3s ease, translate .3s ease, scale .3s ease;
  }
  .chat-message-container:first-child .rtlty .x-risu-rtlty-pair-char,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty .x-risu-rtlty-pair-char,
  .flex-col-reverse:empty + .risu-chat .rtlty .x-risu-rtlty-pair-char {
    left: var(--rtlty-edge);
    transform: rotate(var(--rtlty-tilt-char));
    anchor-name: --rtlty-portrait-char;
  }
  .chat-message-container:first-child .rtlty .x-risu-rtlty-pair-user,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty .x-risu-rtlty-pair-user,
  .flex-col-reverse:empty + .risu-chat .rtlty .x-risu-rtlty-pair-user {
    right: var(--rtlty-edge);
    transform: rotate(var(--rtlty-tilt-user));
  }
  /* 말하는 쪽: 살짝 떠오르고 아래에 옅은 그림자가 집니다.
     변주마다 쓰는 transform·box-shadow를 덮지 않도록 translate·scale·filter만 씁니다. */
  .chat-message-container:first-child .rtlty--char .x-risu-rtlty-pair-char,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty--char .x-risu-rtlty-pair-char,
  .flex-col-reverse:empty + .risu-chat .rtlty--char .x-risu-rtlty-pair-char,
  .chat-message-container:first-child .rtlty--user .x-risu-rtlty-pair-user,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty--user .x-risu-rtlty-pair-user,
  .flex-col-reverse:empty + .risu-chat .rtlty--user .x-risu-rtlty-pair-user {
    translate: 0 -4px;
    scale: 1.015;
    filter: drop-shadow(0 14px 12px rgba(0, 0, 0, .22));
  }
  /* 투명 토글: 왼쪽 초상 안쪽 왼쪽 위 귀퉁이의 작은 단추. 누르면 두 초상이 거의 투명해져 배경이 보입니다.
     초상 높이는 채팅 영역 폭에 따라 달라 CSS 계산으로는 세로 위치를 맞출 수 없으므로, 앵커 위치 지정으로 초상에 붙입니다.
     앵커를 지원하지 않는 브라우저에서는 채팅 영역 위쪽, 초상과 같은 세로선에 놓입니다. */
  .chat-message-container:first-child .rtlty .x-risu-rtlty-fade,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty .x-risu-rtlty-fade,
  .flex-col-reverse:empty + .risu-chat .rtlty .x-risu-rtlty-fade {
    display: block;
    position: fixed;
    z-index: 2;
    top: calc(var(--rtlty-edge) + .6rem);
    left: calc(var(--rtlty-edge) + .6rem);
    margin: 0;
  }
  @supports (anchor-name: --a) {
    .chat-message-container:first-child .rtlty .x-risu-rtlty-fade,
    .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty .x-risu-rtlty-fade,
    .flex-col-reverse:empty + .risu-chat .rtlty .x-risu-rtlty-fade {
      position-anchor: --rtlty-portrait-char;
      top: calc(anchor(top) + .6rem);
      left: calc(anchor(left) + .6rem);
    }
  }
  .rtlty .x-risu-rtlty-fade > summary {
    display: grid;
    place-items: center;
    width: 1.9rem;
    height: 1.9rem;
    border-radius: 50%;
    list-style: none;
    cursor: pointer;
    color: #fff;
    font-size: .95rem;
    line-height: 1;
    background: rgba(0, 0, 0, .32);
    -webkit-backdrop-filter: blur(6px);
    backdrop-filter: blur(6px);
    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .25);
    opacity: .7;
    transition: opacity .2s ease, background .2s ease;
    user-select: none;
  }
  .rtlty .x-risu-rtlty-fade > summary::-webkit-details-marker { display: none; }
  .rtlty .x-risu-rtlty-fade > summary::before { content: "◐"; }
  .rtlty .x-risu-rtlty-fade > summary:hover,
  .rtlty .x-risu-rtlty-fade[open] > summary { opacity: 1; background: rgba(0, 0, 0, .5); }
  .rtlty.rtlty .x-risu-rtlty-pair.x-risu-rtlty-pair:has(> .x-risu-rtlty-fade[open]) :is(.x-risu-rtlty-pair-char, .x-risu-rtlty-pair-user) {
    opacity: .08;
    translate: none;
    scale: none;
    filter: none;
  }
}

/* 휴대폰: 메시지마다 위에 두 초상이 마주 봅니다 */
@media (max-width: 900px) {
  .rtlty.rtlty { display: grid; }
  .rtlty {
    --rtlty-side-w: 6rem;
    grid-template-columns: 1fr 1fr;
    row-gap: .8rem;
    column-gap: .6rem;
    max-width: none;
    padding: var(--rtlty-pad) 0;
  }
  .rtlty__side { display: flex; flex-direction: row; align-items: center; gap: .6rem; min-width: 0; }
  .rtlty__side--char { grid-column: 1; grid-row: 1; justify-content: flex-start; }
  .rtlty__side--user { grid-column: 2; grid-row: 1; flex-direction: row-reverse; justify-content: flex-start; }
  .rtlty__frame { position: relative; width: var(--rtlty-side-w); flex: 0 0 auto; aspect-ratio: 3 / 4; }
  .rtlty__portrait { width: 100%; height: 100%; border-radius: inherit; }
  .rtlty__side-name { min-width: 0; color: var(--rtlty-muted); font-size: .78em; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .rtlty__main { grid-column: 1 / -1; grid-row: 2; }
  .rtlty__speaker { display: none; }
  .rtlty--char .rtlty__side--char .rtlty__side-name, .rtlty--user .rtlty__side--user .rtlty__side-name { color: var(--rtlty-ink); }
  /* 말하는 쪽 초상: 살짝 떠오르고 아래에 옅은 그림자 */
  .rtlty--char .rtlty__side--char .rtlty__frame, .rtlty--user .rtlty__side--user .rtlty__frame {
    translate: 0 -3px;
    scale: 1.04;
    filter: drop-shadow(0 8px 7px rgba(0, 0, 0, .2));
  }
  .rtlty .x-risu-rtlty-pair-char, .rtlty .x-risu-rtlty-pair-user {
    position: absolute;
    top: var(--rtlty-pad);
    width: var(--rtlty-side-w);
    aspect-ratio: 3 / 4;
  }
  .rtlty--user .x-risu-rtlty-pair-char { display: block; left: 0; }
  .rtlty--char .x-risu-rtlty-pair-user { display: block; right: 0; }
}
/* 우표: 흰 테두리와 톱니 가장자리 */
.rtlty__frame {
  padding: 6px;
  background: var(--rtlty-stamp);
  outline: 4px dotted var(--rtlty-hole);
  outline-offset: -2px;
  box-shadow: 0 4px 12px var(--rtlty-shadow);
  transform: rotate(var(--rtlty-tilt-char));
}
.rtlty__side--user .rtlty__frame { transform: rotate(var(--rtlty-tilt-user)); }
.rtlty { --rtlty-tilt-char: -1.5deg; --rtlty-tilt-user: 1.5deg; }
.rtlty .x-risu-rtlty-pair-char, .rtlty .x-risu-rtlty-pair-user {
  border: 6px solid var(--rtlty-stamp);
  background-clip: padding-box;
  outline: 4px dotted var(--rtlty-hole);
  outline-offset: -2px;
  box-shadow: 0 8px 22px var(--rtlty-shadow);
}
@media (max-width: 900px) {
  .rtlty .x-risu-rtlty-pair-char { transform: rotate(var(--rtlty-tilt-char)); }
  .rtlty .x-risu-rtlty-pair-user { transform: rotate(var(--rtlty-tilt-user)); }
}
.rtlty__side-name { font-family: var(--rtlty-font-display); font-size: 1.2em; font-weight: 400; padding: 0 .6em; border-radius: .2rem; background: var(--rtlty-paper); color: var(--rtlty-ink); box-shadow: 0 2px 6px var(--rtlty-shadow); }
.rtlty__main {
  padding: 1.2rem clamp(1rem, 3vw, 1.8rem) .9rem;
  background-color: var(--rtlty-paper);
  background-image: repeating-linear-gradient(to bottom, transparent 0, transparent calc(var(--rtlty-font-size) * var(--rtlty-line-height) - 1px), var(--rtlty-rule) calc(var(--rtlty-font-size) * var(--rtlty-line-height) - 1px), var(--rtlty-rule) calc(var(--rtlty-font-size) * var(--rtlty-line-height)));
  background-position: 0 1.2rem;
  border-radius: .25rem;
  box-shadow: 0 1px 3px var(--rtlty-shadow), 0 10px 26px var(--rtlty-shadow);
}
.rtlty--user .rtlty__main { background-color: var(--rtlty-paper-user); }
.rtlty__footer { margin-top: .7rem; font-family: "Pretendard Variable", "Pretendard", "Noto Sans KR", -apple-system, "Malgun Gothic", sans-serif; font-size: .8em; }
.rtlty__content :is(h1, h2, h3, h4, h5, h6) { --risu-font-family: var(--rtlty-font-body); font-family: var(--rtlty-font-body); }
@media (max-width: 900px) { .rtlty__frame { padding: 4px; } }

/* ── 배색과 소재: 이 블록만 바꾸면 같은 분류의 다른 변주가 됩니다. (미색) ── */
.rtlty {
  --rtlty-paper: #faf6ee;
  --rtlty-paper-user: #f3ede1;
  --rtlty-rule: #ebe2d2;
  --rtlty-ink: #3d342b;
  --rtlty-muted: #8a7d6c;
  --rtlty-accent: #9a6b4b;
  --rtlty-dialog: #7a4a2e;
  --rtlty-stamp: #fffdf8;
  --rtlty-shadow: rgba(80, 55, 25, .12);
  --rtlty-line: #e2d7c4;
  --rtlty-tint: #f0e8da;
  --rtlty-edit-bg: #fffdf8;
}

@import url("https://fonts.googleapis.com/css2?family=Gowun+Batang:wght@400;700&family=Nanum+Pen+Script&display=swap");

/* 바깥 래퍼: 메시지 폭을 확보하고 가운데 정렬합니다. */
.risu-chat > div {
  padding: 0 .75rem;
  margin: auto;
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
}
.risu-chat > div > div {
  width: 100%;
  margin: auto;
  display: flex;
  justify-content: center;
}

/* 글꼴과 크기: 본문 글자 크기는 --rtlty-font-size로 바꿉니다. */
.rtlty {
  --rtlty-bg-fill: transparent;
  --rtlty-blur: none;
  --rtlty-bg-edge: none;
  --rtlty-font-body: "Gowun Batang", "Noto Serif KR", serif;
  --rtlty-font-display: "Nanum Pen Script", "Gowun Batang", cursive;
  --rtlty-font-size: 16px;
  --rtlty-line-height: 1.9;
  --rtlty-para-gap: 0;
  --rtlty-dialog-weight: 700;
  --rtlty-hole: var(--risu-theme-bgcolor, #1e1f24);
}

/* 본문: RisuAI 기본 색·글꼴 변수에 테마 값을 연결합니다. */
.rtlty {
  --risu-font-family: var(--rtlty-font-body);
  --FontColorStandard: var(--rtlty-ink);
  --FontColorBold: var(--rtlty-ink);
  --FontColorItalic: var(--rtlty-muted);
  --FontColorItalicBold: var(--rtlty-muted);
  --FontColorQuote1: var(--rtlty-muted);
  --FontColorQuote2: var(--rtlty-dialog);
  position: relative;
  isolation: isolate;
  width: 100%;
  min-width: 0;
  color: var(--rtlty-ink);
  font-family: var(--rtlty-font-body);
  font-size: var(--rtlty-font-size);
  line-height: var(--rtlty-line-height);
}
.rtlty, .rtlty *, .rtlty *::before, .rtlty *::after { box-sizing: border-box; }
/* 바깥 래퍼 보정(.risu-chat > div > div)이 테마 루트를 flex로 바꾸지 않게 루트 배치를 고정합니다. */
.rtlty.rtlty { display: block; }
.rtlty__content {
  min-width: 0;
  color: var(--rtlty-ink);
  word-break: keep-all;
  overflow-wrap: anywhere;
}
.rtlty__content .chattext {
  --tw-prose-code: var(--rtlty-ink);
  --tw-prose-pre-code: var(--rtlty-ink);
  --tw-prose-pre-bg: var(--rtlty-tint);
  max-width: none;
  color: var(--rtlty-ink);
  font-size: var(--rtlty-font-size) !important;
  line-height: var(--rtlty-line-height) !important;
}
.rtlty__content :is(p, li, td, th, blockquote) {
  font-size: var(--rtlty-font-size);
  line-height: var(--rtlty-line-height);
}
.rtlty__content p { margin: 0 0 var(--rtlty-para-gap); }
.rtlty__content p:last-child { margin-bottom: 0; }
.rtlty__content :is(h1, h2, h3, h4, h5, h6) {
  --risu-font-family: var(--rtlty-font-display);
  margin: 1.3em 0 .55em;
  color: var(--rtlty-ink);
  font-family: var(--rtlty-font-display);
  line-height: 1.4;
  font-weight: 700;
}
.rtlty__content h1 { font-size: calc(var(--rtlty-font-size) * 1.6); }
.rtlty__content h2 { font-size: calc(var(--rtlty-font-size) * 1.35); }
.rtlty__content h3 { font-size: calc(var(--rtlty-font-size) * 1.15); }
.rtlty__content :is(h4, h5, h6) { font-size: var(--rtlty-font-size); }
.rtlty__content strong { font-weight: 700; }
.rtlty__content em { color: var(--rtlty-muted); }
.rtlty__content mark[risu-mark="quote1"],
.rtlty__content mark[risu-mark="blockquote1"] { color: var(--rtlty-muted); background: transparent; }
.rtlty__content mark[risu-mark="quote2"],
.rtlty__content mark[risu-mark="blockquote2"] {
  color: var(--rtlty-dialog);
  font-weight: var(--rtlty-dialog-weight);
  background: transparent;
}
.rtlty__content blockquote {
  margin: 1em 0;
  padding: .3em 1em;
  border-left: 3px solid var(--rtlty-line);
  color: var(--rtlty-muted);
}
.rtlty__content :is(ul, ol) { margin: 1em 0; padding-left: 1.5em; }
.rtlty__content li { margin: .25em 0; color: var(--rtlty-ink); }
.rtlty__content li::marker { color: var(--rtlty-muted); }
.rtlty__content a { color: var(--rtlty-accent); text-decoration: underline; }
.rtlty__content hr { border: 0; border-top: 1px solid var(--rtlty-line); margin: 1.5em 0; }
.rtlty__content code {
  --risu-font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  padding: .1em .3em;
  border-radius: .2em;
  color: var(--rtlty-ink);
  background: var(--rtlty-tint);
  font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  font-size: calc(var(--rtlty-font-size) * .88);
}
.rtlty__content pre {
  max-width: 100%;
  overflow-x: auto;
  padding: .9em 1em;
  color: var(--rtlty-ink);
  background: var(--rtlty-tint);
  border-radius: .35rem;
  font-size: calc(var(--rtlty-font-size) * .88);
  line-height: 1.5;
}
.rtlty__content pre code { padding: 0; background: transparent; color: inherit; white-space: pre; overflow-wrap: normal; }
.rtlty__content table {
  display: block;
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
  margin: 1em 0;
}
.rtlty__content :is(th, td) {
  padding: .5em .7em;
  color: var(--rtlty-ink);
  border-bottom: 1px solid var(--rtlty-line);
  text-align: left;
  vertical-align: top;
}
.rtlty__content th { font-weight: 700; }
.rtlty__content img { display: block; max-width: 100%; height: auto; margin: .75em auto; }
.rtlty__content textarea.message-edit-area {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  color: var(--rtlty-ink) !important;
  background: var(--rtlty-edit-bg) !important;
  border: 1px solid var(--rtlty-line);
  border-radius: .4rem;
  font: inherit;
  font-size: var(--rtlty-font-size) !important;
  line-height: var(--rtlty-line-height) !important;
}

/* 조작부: 생성 정보와 버튼 */
.rtlty__footer {
  --risu-theme-textcolor2: var(--rtlty-muted);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .4rem .75rem;
  min-width: 0;
}
.rtlty__info, .rtlty__actions { min-width: 0; max-width: 100%; }
.rtlty__info > div, .rtlty__actions > div { flex-wrap: wrap; min-width: 0; gap: .3rem; }
.rtlty__actions > div > div { flex-wrap: wrap; min-width: 0; }
.rtlty__footer button {
  background: transparent;
  min-height: 1.9rem;
  padding: .25rem .4rem;
  border-radius: .3rem;
  white-space: normal;
}
.rtlty__footer button:hover { background: var(--rtlty-tint); }
.rtlty :is(a, button, textarea):focus-visible { outline: 2px solid var(--rtlty-accent); outline-offset: 2px; }

/* 아바타 틀: RisuAI가 넣는 배경 이미지 칸을 틀에 맞춥니다. */
.rtlty__portrait { overflow: hidden; background: var(--rtlty-tint); }
.rtlty__portrait > * {
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  background-size: cover !important;
  background-position: center 22% !important;
  border: 0 !important;
  border-radius: inherit !important;
}

.rtlty__bg {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background: var(--rtlty-bg-fill);
  -webkit-backdrop-filter: var(--rtlty-blur);
  backdrop-filter: var(--rtlty-blur);
  box-shadow: var(--rtlty-bg-edge);
}

/* 구조: 편지 양쪽 */


.rtlty {
  --rtlty-col: 44rem;
  --rtlty-gap: clamp(1rem, 2.5vw, 2rem);
  /* PC 고정 초상: 바깥 가장자리에 붙고, 3:4 비율로 칸 폭과 높이 중 먼저 닿는 쪽까지 커집니다.
     남는 폭은 초상과 본문 사이로, 남는 높이는 위아래로 나뉩니다. */
  --rtlty-edge: 1rem;
  --rtlty-fixed-bottom: 5rem; /* 입력창을 피하는 아래 여백 */
  --rtlty-fixed-w: max(8rem, min(calc((100% - var(--rtlty-col)) / 2 - var(--rtlty-gap) - var(--rtlty-edge)), calc((100vh - var(--rtlty-edge) - var(--rtlty-fixed-bottom)) * 3 / 4)));
  --rtlty-pad: 1rem;
  max-width: var(--rtlty-col);
  margin: 0 auto;
  padding: .55rem 0;
}
.rtlty__side { display: none; }
.rtlty__main { min-width: 0; }
.rtlty__speaker { margin-bottom: .45rem; color: var(--rtlty-muted); font-size: .8em; font-weight: 700; letter-spacing: .02em; }
.rtlty--char .rtlty__speaker { color: var(--rtlty-ink); }
/* 정규식이 넣은 조각은 스스로 숨어 있습니다. 이 테마 안에서만 드러냅니다. */
.rtlty .x-risu-rtlty-pair { display: block !important; height: 0; margin: 0; padding: 0; }
.rtlty .x-risu-rtlty-pair-char, .rtlty .x-risu-rtlty-pair-user {
  display: none;
  background-size: cover;
  background-position: center 22%;
}
/* 투명 토글은 PC의 가장 최근 메시지에서만 보입니다. */
.rtlty .x-risu-rtlty-fade { display: none; }

/* 고정 초상이 채팅 영역을 기준으로 놓이게 합니다 (이 테마가 채팅에 있을 때만 걸립니다). */
:has(> .default-chat-screen .rtlty) { transform: translateZ(0); }

/* PC: 가장 최근 메시지 하나에서만 두 초상을 꺼내 채팅 영역 양옆에 고정합니다.
   가장 최근 메시지가 편집 중이라 이미지가 없으면 그 바로 앞 메시지가, 대화가 첫인사뿐이면 첫인사가 맡습니다. */
@media (min-width: 901px) {
  .chat-message-container:first-child .rtlty :is(.x-risu-rtlty-pair-char, .x-risu-rtlty-pair-user),
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty :is(.x-risu-rtlty-pair-char, .x-risu-rtlty-pair-user),
  .flex-col-reverse:empty + .risu-chat .rtlty :is(.x-risu-rtlty-pair-char, .x-risu-rtlty-pair-user) {
    display: block;
    position: fixed;
    z-index: 1;
    /* 입력창을 뺀 영역의 세로 가운데: 위아래를 정하고 margin auto로 가운데에 둡니다 (transform을 쓰지 않아야 토글 앵커가 맞습니다) */
    top: var(--rtlty-edge);
    bottom: var(--rtlty-fixed-bottom);
    margin-block: auto;
    width: var(--rtlty-fixed-w);
    aspect-ratio: 3 / 4;
    transition: opacity .3s ease, filter .3s ease, translate .3s ease, scale .3s ease;
  }
  .chat-message-container:first-child .rtlty .x-risu-rtlty-pair-char,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty .x-risu-rtlty-pair-char,
  .flex-col-reverse:empty + .risu-chat .rtlty .x-risu-rtlty-pair-char {
    left: var(--rtlty-edge);
    transform: rotate(var(--rtlty-tilt-char));
    anchor-name: --rtlty-portrait-char;
  }
  .chat-message-container:first-child .rtlty .x-risu-rtlty-pair-user,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty .x-risu-rtlty-pair-user,
  .flex-col-reverse:empty + .risu-chat .rtlty .x-risu-rtlty-pair-user {
    right: var(--rtlty-edge);
    transform: rotate(var(--rtlty-tilt-user));
  }
  /* 말하는 쪽: 살짝 떠오르고 아래에 옅은 그림자가 집니다.
     변주마다 쓰는 transform·box-shadow를 덮지 않도록 translate·scale·filter만 씁니다. */
  .chat-message-container:first-child .rtlty--char .x-risu-rtlty-pair-char,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty--char .x-risu-rtlty-pair-char,
  .flex-col-reverse:empty + .risu-chat .rtlty--char .x-risu-rtlty-pair-char,
  .chat-message-container:first-child .rtlty--user .x-risu-rtlty-pair-user,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty--user .x-risu-rtlty-pair-user,
  .flex-col-reverse:empty + .risu-chat .rtlty--user .x-risu-rtlty-pair-user {
    translate: 0 -4px;
    scale: 1.015;
    filter: drop-shadow(0 14px 12px rgba(0, 0, 0, .22));
  }
  /* 투명 토글: 왼쪽 초상 안쪽 왼쪽 위 귀퉁이의 작은 단추. 누르면 두 초상이 거의 투명해져 배경이 보입니다.
     초상 높이는 채팅 영역 폭에 따라 달라 CSS 계산으로는 세로 위치를 맞출 수 없으므로, 앵커 위치 지정으로 초상에 붙입니다.
     앵커를 지원하지 않는 브라우저에서는 채팅 영역 위쪽, 초상과 같은 세로선에 놓입니다. */
  .chat-message-container:first-child .rtlty .x-risu-rtlty-fade,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty .x-risu-rtlty-fade,
  .flex-col-reverse:empty + .risu-chat .rtlty .x-risu-rtlty-fade {
    display: block;
    position: fixed;
    z-index: 2;
    top: calc(var(--rtlty-edge) + .6rem);
    left: calc(var(--rtlty-edge) + .6rem);
    margin: 0;
  }
  @supports (anchor-name: --a) {
    .chat-message-container:first-child .rtlty .x-risu-rtlty-fade,
    .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty .x-risu-rtlty-fade,
    .flex-col-reverse:empty + .risu-chat .rtlty .x-risu-rtlty-fade {
      position-anchor: --rtlty-portrait-char;
      top: calc(anchor(top) + .6rem);
      left: calc(anchor(left) + .6rem);
    }
  }
  .rtlty .x-risu-rtlty-fade > summary {
    display: grid;
    place-items: center;
    width: 1.9rem;
    height: 1.9rem;
    border-radius: 50%;
    list-style: none;
    cursor: pointer;
    color: #fff;
    font-size: .95rem;
    line-height: 1;
    background: rgba(0, 0, 0, .32);
    -webkit-backdrop-filter: blur(6px);
    backdrop-filter: blur(6px);
    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .25);
    opacity: .7;
    transition: opacity .2s ease, background .2s ease;
    user-select: none;
  }
  .rtlty .x-risu-rtlty-fade > summary::-webkit-details-marker { display: none; }
  .rtlty .x-risu-rtlty-fade > summary::before { content: "◐"; }
  .rtlty .x-risu-rtlty-fade > summary:hover,
  .rtlty .x-risu-rtlty-fade[open] > summary { opacity: 1; background: rgba(0, 0, 0, .5); }
  .rtlty.rtlty .x-risu-rtlty-pair.x-risu-rtlty-pair:has(> .x-risu-rtlty-fade[open]) :is(.x-risu-rtlty-pair-char, .x-risu-rtlty-pair-user) {
    opacity: .08;
    translate: none;
    scale: none;
    filter: none;
  }
}

/* 휴대폰: 메시지마다 위에 두 초상이 마주 봅니다 */
@media (max-width: 900px) {
  .rtlty.rtlty { display: grid; }
  .rtlty {
    --rtlty-side-w: 6rem;
    grid-template-columns: 1fr 1fr;
    row-gap: .8rem;
    column-gap: .6rem;
    max-width: none;
    padding: var(--rtlty-pad) 0;
  }
  .rtlty__side { display: flex; flex-direction: row; align-items: center; gap: .6rem; min-width: 0; }
  .rtlty__side--char { grid-column: 1; grid-row: 1; justify-content: flex-start; }
  .rtlty__side--user { grid-column: 2; grid-row: 1; flex-direction: row-reverse; justify-content: flex-start; }
  .rtlty__frame { position: relative; width: var(--rtlty-side-w); flex: 0 0 auto; aspect-ratio: 3 / 4; }
  .rtlty__portrait { width: 100%; height: 100%; border-radius: inherit; }
  .rtlty__side-name { min-width: 0; color: var(--rtlty-muted); font-size: .78em; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .rtlty__main { grid-column: 1 / -1; grid-row: 2; }
  .rtlty__speaker { display: none; }
  .rtlty--char .rtlty__side--char .rtlty__side-name, .rtlty--user .rtlty__side--user .rtlty__side-name { color: var(--rtlty-ink); }
  /* 말하는 쪽 초상: 살짝 떠오르고 아래에 옅은 그림자 */
  .rtlty--char .rtlty__side--char .rtlty__frame, .rtlty--user .rtlty__side--user .rtlty__frame {
    translate: 0 -3px;
    scale: 1.04;
    filter: drop-shadow(0 8px 7px rgba(0, 0, 0, .2));
  }
  .rtlty .x-risu-rtlty-pair-char, .rtlty .x-risu-rtlty-pair-user {
    position: absolute;
    top: var(--rtlty-pad);
    width: var(--rtlty-side-w);
    aspect-ratio: 3 / 4;
  }
  .rtlty--user .x-risu-rtlty-pair-char { display: block; left: 0; }
  .rtlty--char .x-risu-rtlty-pair-user { display: block; right: 0; }
}
/* 우표: 흰 테두리와 톱니 가장자리 */
.rtlty__frame {
  padding: 6px;
  background: var(--rtlty-stamp);
  outline: 4px dotted var(--rtlty-hole);
  outline-offset: -2px;
  box-shadow: 0 4px 12px var(--rtlty-shadow);
  transform: rotate(var(--rtlty-tilt-char));
}
.rtlty__side--user .rtlty__frame { transform: rotate(var(--rtlty-tilt-user)); }
.rtlty { --rtlty-tilt-char: -1.5deg; --rtlty-tilt-user: 1.5deg; }
.rtlty .x-risu-rtlty-pair-char, .rtlty .x-risu-rtlty-pair-user {
  border: 6px solid var(--rtlty-stamp);
  background-clip: padding-box;
  outline: 4px dotted var(--rtlty-hole);
  outline-offset: -2px;
  box-shadow: 0 8px 22px var(--rtlty-shadow);
}
@media (max-width: 900px) {
  .rtlty .x-risu-rtlty-pair-char { transform: rotate(var(--rtlty-tilt-char)); }
  .rtlty .x-risu-rtlty-pair-user { transform: rotate(var(--rtlty-tilt-user)); }
}
.rtlty__side-name { font-family: var(--rtlty-font-display); font-size: 1.2em; font-weight: 400; padding: 0 .6em; border-radius: .2rem; background: var(--rtlty-paper); color: var(--rtlty-ink); box-shadow: 0 2px 6px var(--rtlty-shadow); }
.rtlty__main {
  padding: 1.2rem clamp(1rem, 3vw, 1.8rem) .9rem;
  background-color: var(--rtlty-paper);
  background-image: repeating-linear-gradient(to bottom, transparent 0, transparent calc(var(--rtlty-font-size) * var(--rtlty-line-height) - 1px), var(--rtlty-rule) calc(var(--rtlty-font-size) * var(--rtlty-line-height) - 1px), var(--rtlty-rule) calc(var(--rtlty-font-size) * var(--rtlty-line-height)));
  background-position: 0 1.2rem;
  border-radius: .25rem;
  box-shadow: 0 1px 3px var(--rtlty-shadow), 0 10px 26px var(--rtlty-shadow);
}
.rtlty--user .rtlty__main { background-color: var(--rtlty-paper-user); }
.rtlty__footer { margin-top: .7rem; font-family: "Pretendard Variable", "Pretendard", "Noto Sans KR", -apple-system, "Malgun Gothic", sans-serif; font-size: .8em; }
.rtlty__content :is(h1, h2, h3, h4, h5, h6) { --risu-font-family: var(--rtlty-font-body); font-family: var(--rtlty-font-body); }
@media (max-width: 900px) { .rtlty__frame { padding: 4px; } }

/* ── 배색과 소재: 이 블록만 바꾸면 같은 분류의 다른 변주가 됩니다. (크라프트지) ── */
.rtlty {
  --rtlty-paper: #d8c29f;
  --rtlty-paper-user: #cfb791;
  --rtlty-rule: #c4ab84;
  --rtlty-ink: #33261a;
  --rtlty-muted: #6e5940;
  --rtlty-accent: #6f4426;
  --rtlty-dialog: #5a3418;
  --rtlty-stamp: #f4ead8;
  --rtlty-shadow: rgba(60, 40, 15, .2);
  --rtlty-line: #bea47c;
  --rtlty-tint: #cdb68f;
  --rtlty-edit-bg: #e6d5b8;
}

@import url("https://fonts.googleapis.com/css2?family=Gowun+Batang:wght@400;700&family=Nanum+Pen+Script&display=swap");

/* 바깥 래퍼: 메시지 폭을 확보하고 가운데 정렬합니다. */
.risu-chat > div {
  padding: 0 .75rem;
  margin: auto;
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
}
.risu-chat > div > div {
  width: 100%;
  margin: auto;
  display: flex;
  justify-content: center;
}

/* 글꼴과 크기: 본문 글자 크기는 --rtlty-font-size로 바꿉니다. */
.rtlty {
  --rtlty-bg-fill: transparent;
  --rtlty-blur: none;
  --rtlty-bg-edge: none;
  --rtlty-font-body: "Gowun Batang", "Noto Serif KR", serif;
  --rtlty-font-display: "Nanum Pen Script", "Gowun Batang", cursive;
  --rtlty-font-size: 16px;
  --rtlty-line-height: 1.9;
  --rtlty-para-gap: 0;
  --rtlty-dialog-weight: 700;
  --rtlty-hole: var(--risu-theme-bgcolor, #1e1f24);
}

/* 본문: RisuAI 기본 색·글꼴 변수에 테마 값을 연결합니다. */
.rtlty {
  --risu-font-family: var(--rtlty-font-body);
  --FontColorStandard: var(--rtlty-ink);
  --FontColorBold: var(--rtlty-ink);
  --FontColorItalic: var(--rtlty-muted);
  --FontColorItalicBold: var(--rtlty-muted);
  --FontColorQuote1: var(--rtlty-muted);
  --FontColorQuote2: var(--rtlty-dialog);
  position: relative;
  isolation: isolate;
  width: 100%;
  min-width: 0;
  color: var(--rtlty-ink);
  font-family: var(--rtlty-font-body);
  font-size: var(--rtlty-font-size);
  line-height: var(--rtlty-line-height);
}
.rtlty, .rtlty *, .rtlty *::before, .rtlty *::after { box-sizing: border-box; }
/* 바깥 래퍼 보정(.risu-chat > div > div)이 테마 루트를 flex로 바꾸지 않게 루트 배치를 고정합니다. */
.rtlty.rtlty { display: block; }
.rtlty__content {
  min-width: 0;
  color: var(--rtlty-ink);
  word-break: keep-all;
  overflow-wrap: anywhere;
}
.rtlty__content .chattext {
  --tw-prose-code: var(--rtlty-ink);
  --tw-prose-pre-code: var(--rtlty-ink);
  --tw-prose-pre-bg: var(--rtlty-tint);
  max-width: none;
  color: var(--rtlty-ink);
  font-size: var(--rtlty-font-size) !important;
  line-height: var(--rtlty-line-height) !important;
}
.rtlty__content :is(p, li, td, th, blockquote) {
  font-size: var(--rtlty-font-size);
  line-height: var(--rtlty-line-height);
}
.rtlty__content p { margin: 0 0 var(--rtlty-para-gap); }
.rtlty__content p:last-child { margin-bottom: 0; }
.rtlty__content :is(h1, h2, h3, h4, h5, h6) {
  --risu-font-family: var(--rtlty-font-display);
  margin: 1.3em 0 .55em;
  color: var(--rtlty-ink);
  font-family: var(--rtlty-font-display);
  line-height: 1.4;
  font-weight: 700;
}
.rtlty__content h1 { font-size: calc(var(--rtlty-font-size) * 1.6); }
.rtlty__content h2 { font-size: calc(var(--rtlty-font-size) * 1.35); }
.rtlty__content h3 { font-size: calc(var(--rtlty-font-size) * 1.15); }
.rtlty__content :is(h4, h5, h6) { font-size: var(--rtlty-font-size); }
.rtlty__content strong { font-weight: 700; }
.rtlty__content em { color: var(--rtlty-muted); }
.rtlty__content mark[risu-mark="quote1"],
.rtlty__content mark[risu-mark="blockquote1"] { color: var(--rtlty-muted); background: transparent; }
.rtlty__content mark[risu-mark="quote2"],
.rtlty__content mark[risu-mark="blockquote2"] {
  color: var(--rtlty-dialog);
  font-weight: var(--rtlty-dialog-weight);
  background: transparent;
}
.rtlty__content blockquote {
  margin: 1em 0;
  padding: .3em 1em;
  border-left: 3px solid var(--rtlty-line);
  color: var(--rtlty-muted);
}
.rtlty__content :is(ul, ol) { margin: 1em 0; padding-left: 1.5em; }
.rtlty__content li { margin: .25em 0; color: var(--rtlty-ink); }
.rtlty__content li::marker { color: var(--rtlty-muted); }
.rtlty__content a { color: var(--rtlty-accent); text-decoration: underline; }
.rtlty__content hr { border: 0; border-top: 1px solid var(--rtlty-line); margin: 1.5em 0; }
.rtlty__content code {
  --risu-font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  padding: .1em .3em;
  border-radius: .2em;
  color: var(--rtlty-ink);
  background: var(--rtlty-tint);
  font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  font-size: calc(var(--rtlty-font-size) * .88);
}
.rtlty__content pre {
  max-width: 100%;
  overflow-x: auto;
  padding: .9em 1em;
  color: var(--rtlty-ink);
  background: var(--rtlty-tint);
  border-radius: .35rem;
  font-size: calc(var(--rtlty-font-size) * .88);
  line-height: 1.5;
}
.rtlty__content pre code { padding: 0; background: transparent; color: inherit; white-space: pre; overflow-wrap: normal; }
.rtlty__content table {
  display: block;
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
  margin: 1em 0;
}
.rtlty__content :is(th, td) {
  padding: .5em .7em;
  color: var(--rtlty-ink);
  border-bottom: 1px solid var(--rtlty-line);
  text-align: left;
  vertical-align: top;
}
.rtlty__content th { font-weight: 700; }
.rtlty__content img { display: block; max-width: 100%; height: auto; margin: .75em auto; }
.rtlty__content textarea.message-edit-area {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  color: var(--rtlty-ink) !important;
  background: var(--rtlty-edit-bg) !important;
  border: 1px solid var(--rtlty-line);
  border-radius: .4rem;
  font: inherit;
  font-size: var(--rtlty-font-size) !important;
  line-height: var(--rtlty-line-height) !important;
}

/* 조작부: 생성 정보와 버튼 */
.rtlty__footer {
  --risu-theme-textcolor2: var(--rtlty-muted);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .4rem .75rem;
  min-width: 0;
}
.rtlty__info, .rtlty__actions { min-width: 0; max-width: 100%; }
.rtlty__info > div, .rtlty__actions > div { flex-wrap: wrap; min-width: 0; gap: .3rem; }
.rtlty__actions > div > div { flex-wrap: wrap; min-width: 0; }
.rtlty__footer button {
  background: transparent;
  min-height: 1.9rem;
  padding: .25rem .4rem;
  border-radius: .3rem;
  white-space: normal;
}
.rtlty__footer button:hover { background: var(--rtlty-tint); }
.rtlty :is(a, button, textarea):focus-visible { outline: 2px solid var(--rtlty-accent); outline-offset: 2px; }

/* 아바타 틀: RisuAI가 넣는 배경 이미지 칸을 틀에 맞춥니다. */
.rtlty__portrait { overflow: hidden; background: var(--rtlty-tint); }
.rtlty__portrait > * {
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  background-size: cover !important;
  background-position: center 22% !important;
  border: 0 !important;
  border-radius: inherit !important;
}

.rtlty__bg {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background: var(--rtlty-bg-fill);
  -webkit-backdrop-filter: var(--rtlty-blur);
  backdrop-filter: var(--rtlty-blur);
  box-shadow: var(--rtlty-bg-edge);
}

/* 구조: 편지 양쪽 */


.rtlty {
  --rtlty-col: 44rem;
  --rtlty-gap: clamp(1rem, 2.5vw, 2rem);
  /* PC 고정 초상: 바깥 가장자리에 붙고, 3:4 비율로 칸 폭과 높이 중 먼저 닿는 쪽까지 커집니다.
     남는 폭은 초상과 본문 사이로, 남는 높이는 위아래로 나뉩니다. */
  --rtlty-edge: 1rem;
  --rtlty-fixed-bottom: 5rem; /* 입력창을 피하는 아래 여백 */
  --rtlty-fixed-w: max(8rem, min(calc((100% - var(--rtlty-col)) / 2 - var(--rtlty-gap) - var(--rtlty-edge)), calc((100vh - var(--rtlty-edge) - var(--rtlty-fixed-bottom)) * 3 / 4)));
  --rtlty-pad: 1rem;
  max-width: var(--rtlty-col);
  margin: 0 auto;
  padding: .55rem 0;
}
.rtlty__side { display: none; }
.rtlty__main { min-width: 0; }
.rtlty__speaker { margin-bottom: .45rem; color: var(--rtlty-muted); font-size: .8em; font-weight: 700; letter-spacing: .02em; }
.rtlty--char .rtlty__speaker { color: var(--rtlty-ink); }
/* 정규식이 넣은 조각은 스스로 숨어 있습니다. 이 테마 안에서만 드러냅니다. */
.rtlty .x-risu-rtlty-pair { display: block !important; height: 0; margin: 0; padding: 0; }
.rtlty .x-risu-rtlty-pair-char, .rtlty .x-risu-rtlty-pair-user {
  display: none;
  background-size: cover;
  background-position: center 22%;
}
/* 투명 토글은 PC의 가장 최근 메시지에서만 보입니다. */
.rtlty .x-risu-rtlty-fade { display: none; }

/* 고정 초상이 채팅 영역을 기준으로 놓이게 합니다 (이 테마가 채팅에 있을 때만 걸립니다). */
:has(> .default-chat-screen .rtlty) { transform: translateZ(0); }

/* PC: 가장 최근 메시지 하나에서만 두 초상을 꺼내 채팅 영역 양옆에 고정합니다.
   가장 최근 메시지가 편집 중이라 이미지가 없으면 그 바로 앞 메시지가, 대화가 첫인사뿐이면 첫인사가 맡습니다. */
@media (min-width: 901px) {
  .chat-message-container:first-child .rtlty :is(.x-risu-rtlty-pair-char, .x-risu-rtlty-pair-user),
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty :is(.x-risu-rtlty-pair-char, .x-risu-rtlty-pair-user),
  .flex-col-reverse:empty + .risu-chat .rtlty :is(.x-risu-rtlty-pair-char, .x-risu-rtlty-pair-user) {
    display: block;
    position: fixed;
    z-index: 1;
    /* 입력창을 뺀 영역의 세로 가운데: 위아래를 정하고 margin auto로 가운데에 둡니다 (transform을 쓰지 않아야 토글 앵커가 맞습니다) */
    top: var(--rtlty-edge);
    bottom: var(--rtlty-fixed-bottom);
    margin-block: auto;
    width: var(--rtlty-fixed-w);
    aspect-ratio: 3 / 4;
    transition: opacity .3s ease, filter .3s ease, translate .3s ease, scale .3s ease;
  }
  .chat-message-container:first-child .rtlty .x-risu-rtlty-pair-char,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty .x-risu-rtlty-pair-char,
  .flex-col-reverse:empty + .risu-chat .rtlty .x-risu-rtlty-pair-char {
    left: var(--rtlty-edge);
    transform: rotate(var(--rtlty-tilt-char));
    anchor-name: --rtlty-portrait-char;
  }
  .chat-message-container:first-child .rtlty .x-risu-rtlty-pair-user,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty .x-risu-rtlty-pair-user,
  .flex-col-reverse:empty + .risu-chat .rtlty .x-risu-rtlty-pair-user {
    right: var(--rtlty-edge);
    transform: rotate(var(--rtlty-tilt-user));
  }
  /* 말하는 쪽: 살짝 떠오르고 아래에 옅은 그림자가 집니다.
     변주마다 쓰는 transform·box-shadow를 덮지 않도록 translate·scale·filter만 씁니다. */
  .chat-message-container:first-child .rtlty--char .x-risu-rtlty-pair-char,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty--char .x-risu-rtlty-pair-char,
  .flex-col-reverse:empty + .risu-chat .rtlty--char .x-risu-rtlty-pair-char,
  .chat-message-container:first-child .rtlty--user .x-risu-rtlty-pair-user,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty--user .x-risu-rtlty-pair-user,
  .flex-col-reverse:empty + .risu-chat .rtlty--user .x-risu-rtlty-pair-user {
    translate: 0 -4px;
    scale: 1.015;
    filter: drop-shadow(0 14px 12px rgba(0, 0, 0, .22));
  }
  /* 투명 토글: 왼쪽 초상 안쪽 왼쪽 위 귀퉁이의 작은 단추. 누르면 두 초상이 거의 투명해져 배경이 보입니다.
     초상 높이는 채팅 영역 폭에 따라 달라 CSS 계산으로는 세로 위치를 맞출 수 없으므로, 앵커 위치 지정으로 초상에 붙입니다.
     앵커를 지원하지 않는 브라우저에서는 채팅 영역 위쪽, 초상과 같은 세로선에 놓입니다. */
  .chat-message-container:first-child .rtlty .x-risu-rtlty-fade,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty .x-risu-rtlty-fade,
  .flex-col-reverse:empty + .risu-chat .rtlty .x-risu-rtlty-fade {
    display: block;
    position: fixed;
    z-index: 2;
    top: calc(var(--rtlty-edge) + .6rem);
    left: calc(var(--rtlty-edge) + .6rem);
    margin: 0;
  }
  @supports (anchor-name: --a) {
    .chat-message-container:first-child .rtlty .x-risu-rtlty-fade,
    .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty .x-risu-rtlty-fade,
    .flex-col-reverse:empty + .risu-chat .rtlty .x-risu-rtlty-fade {
      position-anchor: --rtlty-portrait-char;
      top: calc(anchor(top) + .6rem);
      left: calc(anchor(left) + .6rem);
    }
  }
  .rtlty .x-risu-rtlty-fade > summary {
    display: grid;
    place-items: center;
    width: 1.9rem;
    height: 1.9rem;
    border-radius: 50%;
    list-style: none;
    cursor: pointer;
    color: #fff;
    font-size: .95rem;
    line-height: 1;
    background: rgba(0, 0, 0, .32);
    -webkit-backdrop-filter: blur(6px);
    backdrop-filter: blur(6px);
    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .25);
    opacity: .7;
    transition: opacity .2s ease, background .2s ease;
    user-select: none;
  }
  .rtlty .x-risu-rtlty-fade > summary::-webkit-details-marker { display: none; }
  .rtlty .x-risu-rtlty-fade > summary::before { content: "◐"; }
  .rtlty .x-risu-rtlty-fade > summary:hover,
  .rtlty .x-risu-rtlty-fade[open] > summary { opacity: 1; background: rgba(0, 0, 0, .5); }
  .rtlty.rtlty .x-risu-rtlty-pair.x-risu-rtlty-pair:has(> .x-risu-rtlty-fade[open]) :is(.x-risu-rtlty-pair-char, .x-risu-rtlty-pair-user) {
    opacity: .08;
    translate: none;
    scale: none;
    filter: none;
  }
}

/* 휴대폰: 메시지마다 위에 두 초상이 마주 봅니다 */
@media (max-width: 900px) {
  .rtlty.rtlty { display: grid; }
  .rtlty {
    --rtlty-side-w: 6rem;
    grid-template-columns: 1fr 1fr;
    row-gap: .8rem;
    column-gap: .6rem;
    max-width: none;
    padding: var(--rtlty-pad) 0;
  }
  .rtlty__side { display: flex; flex-direction: row; align-items: center; gap: .6rem; min-width: 0; }
  .rtlty__side--char { grid-column: 1; grid-row: 1; justify-content: flex-start; }
  .rtlty__side--user { grid-column: 2; grid-row: 1; flex-direction: row-reverse; justify-content: flex-start; }
  .rtlty__frame { position: relative; width: var(--rtlty-side-w); flex: 0 0 auto; aspect-ratio: 3 / 4; }
  .rtlty__portrait { width: 100%; height: 100%; border-radius: inherit; }
  .rtlty__side-name { min-width: 0; color: var(--rtlty-muted); font-size: .78em; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .rtlty__main { grid-column: 1 / -1; grid-row: 2; }
  .rtlty__speaker { display: none; }
  .rtlty--char .rtlty__side--char .rtlty__side-name, .rtlty--user .rtlty__side--user .rtlty__side-name { color: var(--rtlty-ink); }
  /* 말하는 쪽 초상: 살짝 떠오르고 아래에 옅은 그림자 */
  .rtlty--char .rtlty__side--char .rtlty__frame, .rtlty--user .rtlty__side--user .rtlty__frame {
    translate: 0 -3px;
    scale: 1.04;
    filter: drop-shadow(0 8px 7px rgba(0, 0, 0, .2));
  }
  .rtlty .x-risu-rtlty-pair-char, .rtlty .x-risu-rtlty-pair-user {
    position: absolute;
    top: var(--rtlty-pad);
    width: var(--rtlty-side-w);
    aspect-ratio: 3 / 4;
  }
  .rtlty--user .x-risu-rtlty-pair-char { display: block; left: 0; }
  .rtlty--char .x-risu-rtlty-pair-user { display: block; right: 0; }
}
/* 우표: 흰 테두리와 톱니 가장자리 */
.rtlty__frame {
  padding: 6px;
  background: var(--rtlty-stamp);
  outline: 4px dotted var(--rtlty-hole);
  outline-offset: -2px;
  box-shadow: 0 4px 12px var(--rtlty-shadow);
  transform: rotate(var(--rtlty-tilt-char));
}
.rtlty__side--user .rtlty__frame { transform: rotate(var(--rtlty-tilt-user)); }
.rtlty { --rtlty-tilt-char: -1.5deg; --rtlty-tilt-user: 1.5deg; }
.rtlty .x-risu-rtlty-pair-char, .rtlty .x-risu-rtlty-pair-user {
  border: 6px solid var(--rtlty-stamp);
  background-clip: padding-box;
  outline: 4px dotted var(--rtlty-hole);
  outline-offset: -2px;
  box-shadow: 0 8px 22px var(--rtlty-shadow);
}
@media (max-width: 900px) {
  .rtlty .x-risu-rtlty-pair-char { transform: rotate(var(--rtlty-tilt-char)); }
  .rtlty .x-risu-rtlty-pair-user { transform: rotate(var(--rtlty-tilt-user)); }
}
.rtlty__side-name { font-family: var(--rtlty-font-display); font-size: 1.2em; font-weight: 400; padding: 0 .6em; border-radius: .2rem; background: var(--rtlty-paper); color: var(--rtlty-ink); box-shadow: 0 2px 6px var(--rtlty-shadow); }
.rtlty__main {
  padding: 1.2rem clamp(1rem, 3vw, 1.8rem) .9rem;
  background-color: var(--rtlty-paper);
  background-image: repeating-linear-gradient(to bottom, transparent 0, transparent calc(var(--rtlty-font-size) * var(--rtlty-line-height) - 1px), var(--rtlty-rule) calc(var(--rtlty-font-size) * var(--rtlty-line-height) - 1px), var(--rtlty-rule) calc(var(--rtlty-font-size) * var(--rtlty-line-height)));
  background-position: 0 1.2rem;
  border-radius: .25rem;
  box-shadow: 0 1px 3px var(--rtlty-shadow), 0 10px 26px var(--rtlty-shadow);
}
.rtlty--user .rtlty__main { background-color: var(--rtlty-paper-user); }
.rtlty__footer { margin-top: .7rem; font-family: "Pretendard Variable", "Pretendard", "Noto Sans KR", -apple-system, "Malgun Gothic", sans-serif; font-size: .8em; }
.rtlty__content :is(h1, h2, h3, h4, h5, h6) { --risu-font-family: var(--rtlty-font-body); font-family: var(--rtlty-font-body); }
@media (max-width: 900px) { .rtlty__frame { padding: 4px; } }

/* ── 배색과 소재: 이 블록만 바꾸면 같은 분류의 다른 변주가 됩니다. (남색 편지지) ── */
.rtlty {
  --rtlty-paper: #1f2740;
  --rtlty-paper-user: #242d48;
  --rtlty-rule: #2c3552;
  --rtlty-ink: #e6e2d6;
  --rtlty-muted: #a3a7b8;
  --rtlty-accent: #c9b07a;
  --rtlty-dialog: #e5cf9a;
  --rtlty-stamp: #e9e4d6;
  --rtlty-shadow: rgba(0, 0, 0, .35);
  --rtlty-line: #333d5c;
  --rtlty-tint: #2a3350;
  --rtlty-edit-bg: #1b2238;
}

@import url("https://fonts.googleapis.com/css2?family=Gowun+Batang:wght@400;700&family=Nanum+Pen+Script&display=swap");

/* 바깥 래퍼: 메시지 폭을 확보하고 가운데 정렬합니다. */
.risu-chat > div {
  padding: 0 .75rem;
  margin: auto;
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
}
.risu-chat > div > div {
  width: 100%;
  margin: auto;
  display: flex;
  justify-content: center;
}

/* 글꼴과 크기: 본문 글자 크기는 --rtlty-font-size로 바꿉니다. */
.rtlty {
  --rtlty-bg-fill: transparent;
  --rtlty-blur: none;
  --rtlty-bg-edge: none;
  --rtlty-font-body: "Gowun Batang", "Noto Serif KR", serif;
  --rtlty-font-display: "Nanum Pen Script", "Gowun Batang", cursive;
  --rtlty-font-size: 16px;
  --rtlty-line-height: 1.9;
  --rtlty-para-gap: 0;
  --rtlty-dialog-weight: 700;
  --rtlty-hole: var(--risu-theme-bgcolor, #1e1f24);
}

/* 본문: RisuAI 기본 색·글꼴 변수에 테마 값을 연결합니다. */
.rtlty {
  --risu-font-family: var(--rtlty-font-body);
  --FontColorStandard: var(--rtlty-ink);
  --FontColorBold: var(--rtlty-ink);
  --FontColorItalic: var(--rtlty-muted);
  --FontColorItalicBold: var(--rtlty-muted);
  --FontColorQuote1: var(--rtlty-muted);
  --FontColorQuote2: var(--rtlty-dialog);
  position: relative;
  isolation: isolate;
  width: 100%;
  min-width: 0;
  color: var(--rtlty-ink);
  font-family: var(--rtlty-font-body);
  font-size: var(--rtlty-font-size);
  line-height: var(--rtlty-line-height);
}
.rtlty, .rtlty *, .rtlty *::before, .rtlty *::after { box-sizing: border-box; }
/* 바깥 래퍼 보정(.risu-chat > div > div)이 테마 루트를 flex로 바꾸지 않게 루트 배치를 고정합니다. */
.rtlty.rtlty { display: block; }
.rtlty__content {
  min-width: 0;
  color: var(--rtlty-ink);
  word-break: keep-all;
  overflow-wrap: anywhere;
}
.rtlty__content .chattext {
  --tw-prose-code: var(--rtlty-ink);
  --tw-prose-pre-code: var(--rtlty-ink);
  --tw-prose-pre-bg: var(--rtlty-tint);
  max-width: none;
  color: var(--rtlty-ink);
  font-size: var(--rtlty-font-size) !important;
  line-height: var(--rtlty-line-height) !important;
}
.rtlty__content :is(p, li, td, th, blockquote) {
  font-size: var(--rtlty-font-size);
  line-height: var(--rtlty-line-height);
}
.rtlty__content p { margin: 0 0 var(--rtlty-para-gap); }
.rtlty__content p:last-child { margin-bottom: 0; }
.rtlty__content :is(h1, h2, h3, h4, h5, h6) {
  --risu-font-family: var(--rtlty-font-display);
  margin: 1.3em 0 .55em;
  color: var(--rtlty-ink);
  font-family: var(--rtlty-font-display);
  line-height: 1.4;
  font-weight: 700;
}
.rtlty__content h1 { font-size: calc(var(--rtlty-font-size) * 1.6); }
.rtlty__content h2 { font-size: calc(var(--rtlty-font-size) * 1.35); }
.rtlty__content h3 { font-size: calc(var(--rtlty-font-size) * 1.15); }
.rtlty__content :is(h4, h5, h6) { font-size: var(--rtlty-font-size); }
.rtlty__content strong { font-weight: 700; }
.rtlty__content em { color: var(--rtlty-muted); }
.rtlty__content mark[risu-mark="quote1"],
.rtlty__content mark[risu-mark="blockquote1"] { color: var(--rtlty-muted); background: transparent; }
.rtlty__content mark[risu-mark="quote2"],
.rtlty__content mark[risu-mark="blockquote2"] {
  color: var(--rtlty-dialog);
  font-weight: var(--rtlty-dialog-weight);
  background: transparent;
}
.rtlty__content blockquote {
  margin: 1em 0;
  padding: .3em 1em;
  border-left: 3px solid var(--rtlty-line);
  color: var(--rtlty-muted);
}
.rtlty__content :is(ul, ol) { margin: 1em 0; padding-left: 1.5em; }
.rtlty__content li { margin: .25em 0; color: var(--rtlty-ink); }
.rtlty__content li::marker { color: var(--rtlty-muted); }
.rtlty__content a { color: var(--rtlty-accent); text-decoration: underline; }
.rtlty__content hr { border: 0; border-top: 1px solid var(--rtlty-line); margin: 1.5em 0; }
.rtlty__content code {
  --risu-font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  padding: .1em .3em;
  border-radius: .2em;
  color: var(--rtlty-ink);
  background: var(--rtlty-tint);
  font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  font-size: calc(var(--rtlty-font-size) * .88);
}
.rtlty__content pre {
  max-width: 100%;
  overflow-x: auto;
  padding: .9em 1em;
  color: var(--rtlty-ink);
  background: var(--rtlty-tint);
  border-radius: .35rem;
  font-size: calc(var(--rtlty-font-size) * .88);
  line-height: 1.5;
}
.rtlty__content pre code { padding: 0; background: transparent; color: inherit; white-space: pre; overflow-wrap: normal; }
.rtlty__content table {
  display: block;
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
  margin: 1em 0;
}
.rtlty__content :is(th, td) {
  padding: .5em .7em;
  color: var(--rtlty-ink);
  border-bottom: 1px solid var(--rtlty-line);
  text-align: left;
  vertical-align: top;
}
.rtlty__content th { font-weight: 700; }
.rtlty__content img { display: block; max-width: 100%; height: auto; margin: .75em auto; }
.rtlty__content textarea.message-edit-area {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  color: var(--rtlty-ink) !important;
  background: var(--rtlty-edit-bg) !important;
  border: 1px solid var(--rtlty-line);
  border-radius: .4rem;
  font: inherit;
  font-size: var(--rtlty-font-size) !important;
  line-height: var(--rtlty-line-height) !important;
}

/* 조작부: 생성 정보와 버튼 */
.rtlty__footer {
  --risu-theme-textcolor2: var(--rtlty-muted);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .4rem .75rem;
  min-width: 0;
}
.rtlty__info, .rtlty__actions { min-width: 0; max-width: 100%; }
.rtlty__info > div, .rtlty__actions > div { flex-wrap: wrap; min-width: 0; gap: .3rem; }
.rtlty__actions > div > div { flex-wrap: wrap; min-width: 0; }
.rtlty__footer button {
  background: transparent;
  min-height: 1.9rem;
  padding: .25rem .4rem;
  border-radius: .3rem;
  white-space: normal;
}
.rtlty__footer button:hover { background: var(--rtlty-tint); }
.rtlty :is(a, button, textarea):focus-visible { outline: 2px solid var(--rtlty-accent); outline-offset: 2px; }

/* 아바타 틀: RisuAI가 넣는 배경 이미지 칸을 틀에 맞춥니다. */
.rtlty__portrait { overflow: hidden; background: var(--rtlty-tint); }
.rtlty__portrait > * {
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  background-size: cover !important;
  background-position: center 22% !important;
  border: 0 !important;
  border-radius: inherit !important;
}

.rtlty__bg {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background: var(--rtlty-bg-fill);
  -webkit-backdrop-filter: var(--rtlty-blur);
  backdrop-filter: var(--rtlty-blur);
  box-shadow: var(--rtlty-bg-edge);
}

/* 구조: 편지 양쪽 */


.rtlty {
  --rtlty-col: 44rem;
  --rtlty-gap: clamp(1rem, 2.5vw, 2rem);
  /* PC 고정 초상: 바깥 가장자리에 붙고, 3:4 비율로 칸 폭과 높이 중 먼저 닿는 쪽까지 커집니다.
     남는 폭은 초상과 본문 사이로, 남는 높이는 위아래로 나뉩니다. */
  --rtlty-edge: 1rem;
  --rtlty-fixed-bottom: 5rem; /* 입력창을 피하는 아래 여백 */
  --rtlty-fixed-w: max(8rem, min(calc((100% - var(--rtlty-col)) / 2 - var(--rtlty-gap) - var(--rtlty-edge)), calc((100vh - var(--rtlty-edge) - var(--rtlty-fixed-bottom)) * 3 / 4)));
  --rtlty-pad: 1rem;
  max-width: var(--rtlty-col);
  margin: 0 auto;
  padding: .55rem 0;
}
.rtlty__side { display: none; }
.rtlty__main { min-width: 0; }
.rtlty__speaker { margin-bottom: .45rem; color: var(--rtlty-muted); font-size: .8em; font-weight: 700; letter-spacing: .02em; }
.rtlty--char .rtlty__speaker { color: var(--rtlty-ink); }
/* 정규식이 넣은 조각은 스스로 숨어 있습니다. 이 테마 안에서만 드러냅니다. */
.rtlty .x-risu-rtlty-pair { display: block !important; height: 0; margin: 0; padding: 0; }
.rtlty .x-risu-rtlty-pair-char, .rtlty .x-risu-rtlty-pair-user {
  display: none;
  background-size: cover;
  background-position: center 22%;
}
/* 투명 토글은 PC의 가장 최근 메시지에서만 보입니다. */
.rtlty .x-risu-rtlty-fade { display: none; }

/* 고정 초상이 채팅 영역을 기준으로 놓이게 합니다 (이 테마가 채팅에 있을 때만 걸립니다). */
:has(> .default-chat-screen .rtlty) { transform: translateZ(0); }

/* PC: 가장 최근 메시지 하나에서만 두 초상을 꺼내 채팅 영역 양옆에 고정합니다.
   가장 최근 메시지가 편집 중이라 이미지가 없으면 그 바로 앞 메시지가, 대화가 첫인사뿐이면 첫인사가 맡습니다. */
@media (min-width: 901px) {
  .chat-message-container:first-child .rtlty :is(.x-risu-rtlty-pair-char, .x-risu-rtlty-pair-user),
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty :is(.x-risu-rtlty-pair-char, .x-risu-rtlty-pair-user),
  .flex-col-reverse:empty + .risu-chat .rtlty :is(.x-risu-rtlty-pair-char, .x-risu-rtlty-pair-user) {
    display: block;
    position: fixed;
    z-index: 1;
    /* 입력창을 뺀 영역의 세로 가운데: 위아래를 정하고 margin auto로 가운데에 둡니다 (transform을 쓰지 않아야 토글 앵커가 맞습니다) */
    top: var(--rtlty-edge);
    bottom: var(--rtlty-fixed-bottom);
    margin-block: auto;
    width: var(--rtlty-fixed-w);
    aspect-ratio: 3 / 4;
    transition: opacity .3s ease, filter .3s ease, translate .3s ease, scale .3s ease;
  }
  .chat-message-container:first-child .rtlty .x-risu-rtlty-pair-char,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty .x-risu-rtlty-pair-char,
  .flex-col-reverse:empty + .risu-chat .rtlty .x-risu-rtlty-pair-char {
    left: var(--rtlty-edge);
    transform: rotate(var(--rtlty-tilt-char));
    anchor-name: --rtlty-portrait-char;
  }
  .chat-message-container:first-child .rtlty .x-risu-rtlty-pair-user,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty .x-risu-rtlty-pair-user,
  .flex-col-reverse:empty + .risu-chat .rtlty .x-risu-rtlty-pair-user {
    right: var(--rtlty-edge);
    transform: rotate(var(--rtlty-tilt-user));
  }
  /* 말하는 쪽: 살짝 떠오르고 아래에 옅은 그림자가 집니다.
     변주마다 쓰는 transform·box-shadow를 덮지 않도록 translate·scale·filter만 씁니다. */
  .chat-message-container:first-child .rtlty--char .x-risu-rtlty-pair-char,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty--char .x-risu-rtlty-pair-char,
  .flex-col-reverse:empty + .risu-chat .rtlty--char .x-risu-rtlty-pair-char,
  .chat-message-container:first-child .rtlty--user .x-risu-rtlty-pair-user,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty--user .x-risu-rtlty-pair-user,
  .flex-col-reverse:empty + .risu-chat .rtlty--user .x-risu-rtlty-pair-user {
    translate: 0 -4px;
    scale: 1.015;
    filter: drop-shadow(0 14px 12px rgba(0, 0, 0, .22));
  }
  /* 투명 토글: 왼쪽 초상 안쪽 왼쪽 위 귀퉁이의 작은 단추. 누르면 두 초상이 거의 투명해져 배경이 보입니다.
     초상 높이는 채팅 영역 폭에 따라 달라 CSS 계산으로는 세로 위치를 맞출 수 없으므로, 앵커 위치 지정으로 초상에 붙입니다.
     앵커를 지원하지 않는 브라우저에서는 채팅 영역 위쪽, 초상과 같은 세로선에 놓입니다. */
  .chat-message-container:first-child .rtlty .x-risu-rtlty-fade,
  .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty .x-risu-rtlty-fade,
  .flex-col-reverse:empty + .risu-chat .rtlty .x-risu-rtlty-fade {
    display: block;
    position: fixed;
    z-index: 2;
    top: calc(var(--rtlty-edge) + .6rem);
    left: calc(var(--rtlty-edge) + .6rem);
    margin: 0;
  }
  @supports (anchor-name: --a) {
    .chat-message-container:first-child .rtlty .x-risu-rtlty-fade,
    .chat-message-container:first-child:not(:has(.x-risu-rtlty-pair)) + .chat-message-container .rtlty .x-risu-rtlty-fade,
    .flex-col-reverse:empty + .risu-chat .rtlty .x-risu-rtlty-fade {
      position-anchor: --rtlty-portrait-char;
      top: calc(anchor(top) + .6rem);
      left: calc(anchor(left) + .6rem);
    }
  }
  .rtlty .x-risu-rtlty-fade > summary {
    display: grid;
    place-items: center;
    width: 1.9rem;
    height: 1.9rem;
    border-radius: 50%;
    list-style: none;
    cursor: pointer;
    color: #fff;
    font-size: .95rem;
    line-height: 1;
    background: rgba(0, 0, 0, .32);
    -webkit-backdrop-filter: blur(6px);
    backdrop-filter: blur(6px);
    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .25);
    opacity: .7;
    transition: opacity .2s ease, background .2s ease;
    user-select: none;
  }
  .rtlty .x-risu-rtlty-fade > summary::-webkit-details-marker { display: none; }
  .rtlty .x-risu-rtlty-fade > summary::before { content: "◐"; }
  .rtlty .x-risu-rtlty-fade > summary:hover,
  .rtlty .x-risu-rtlty-fade[open] > summary { opacity: 1; background: rgba(0, 0, 0, .5); }
  .rtlty.rtlty .x-risu-rtlty-pair.x-risu-rtlty-pair:has(> .x-risu-rtlty-fade[open]) :is(.x-risu-rtlty-pair-char, .x-risu-rtlty-pair-user) {
    opacity: .08;
    translate: none;
    scale: none;
    filter: none;
  }
}

/* 휴대폰: 메시지마다 위에 두 초상이 마주 봅니다 */
@media (max-width: 900px) {
  .rtlty.rtlty { display: grid; }
  .rtlty {
    --rtlty-side-w: 6rem;
    grid-template-columns: 1fr 1fr;
    row-gap: .8rem;
    column-gap: .6rem;
    max-width: none;
    padding: var(--rtlty-pad) 0;
  }
  .rtlty__side { display: flex; flex-direction: row; align-items: center; gap: .6rem; min-width: 0; }
  .rtlty__side--char { grid-column: 1; grid-row: 1; justify-content: flex-start; }
  .rtlty__side--user { grid-column: 2; grid-row: 1; flex-direction: row-reverse; justify-content: flex-start; }
  .rtlty__frame { position: relative; width: var(--rtlty-side-w); flex: 0 0 auto; aspect-ratio: 3 / 4; }
  .rtlty__portrait { width: 100%; height: 100%; border-radius: inherit; }
  .rtlty__side-name { min-width: 0; color: var(--rtlty-muted); font-size: .78em; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .rtlty__main { grid-column: 1 / -1; grid-row: 2; }
  .rtlty__speaker { display: none; }
  .rtlty--char .rtlty__side--char .rtlty__side-name, .rtlty--user .rtlty__side--user .rtlty__side-name { color: var(--rtlty-ink); }
  /* 말하는 쪽 초상: 살짝 떠오르고 아래에 옅은 그림자 */
  .rtlty--char .rtlty__side--char .rtlty__frame, .rtlty--user .rtlty__side--user .rtlty__frame {
    translate: 0 -3px;
    scale: 1.04;
    filter: drop-shadow(0 8px 7px rgba(0, 0, 0, .2));
  }
  .rtlty .x-risu-rtlty-pair-char, .rtlty .x-risu-rtlty-pair-user {
    position: absolute;
    top: var(--rtlty-pad);
    width: var(--rtlty-side-w);
    aspect-ratio: 3 / 4;
  }
  .rtlty--user .x-risu-rtlty-pair-char { display: block; left: 0; }
  .rtlty--char .x-risu-rtlty-pair-user { display: block; right: 0; }
}
/* 우표: 흰 테두리와 톱니 가장자리 */
.rtlty__frame {
  padding: 6px;
  background: var(--rtlty-stamp);
  outline: 4px dotted var(--rtlty-hole);
  outline-offset: -2px;
  box-shadow: 0 4px 12px var(--rtlty-shadow);
  transform: rotate(var(--rtlty-tilt-char));
}
.rtlty__side--user .rtlty__frame { transform: rotate(var(--rtlty-tilt-user)); }
.rtlty { --rtlty-tilt-char: -1.5deg; --rtlty-tilt-user: 1.5deg; }
.rtlty .x-risu-rtlty-pair-char, .rtlty .x-risu-rtlty-pair-user {
  border: 6px solid var(--rtlty-stamp);
  background-clip: padding-box;
  outline: 4px dotted var(--rtlty-hole);
  outline-offset: -2px;
  box-shadow: 0 8px 22px var(--rtlty-shadow);
}
@media (max-width: 900px) {
  .rtlty .x-risu-rtlty-pair-char { transform: rotate(var(--rtlty-tilt-char)); }
  .rtlty .x-risu-rtlty-pair-user { transform: rotate(var(--rtlty-tilt-user)); }
}
.rtlty__side-name { font-family: var(--rtlty-font-display); font-size: 1.2em; font-weight: 400; padding: 0 .6em; border-radius: .2rem; background: var(--rtlty-paper); color: var(--rtlty-ink); box-shadow: 0 2px 6px var(--rtlty-shadow); }
.rtlty__main {
  padding: 1.2rem clamp(1rem, 3vw, 1.8rem) .9rem;
  background-color: var(--rtlty-paper);
  background-image: repeating-linear-gradient(to bottom, transparent 0, transparent calc(var(--rtlty-font-size) * var(--rtlty-line-height) - 1px), var(--rtlty-rule) calc(var(--rtlty-font-size) * var(--rtlty-line-height) - 1px), var(--rtlty-rule) calc(var(--rtlty-font-size) * var(--rtlty-line-height)));
  background-position: 0 1.2rem;
  border-radius: .25rem;
  box-shadow: 0 1px 3px var(--rtlty-shadow), 0 10px 26px var(--rtlty-shadow);
}
.rtlty--user .rtlty__main { background-color: var(--rtlty-paper-user); }
.rtlty__footer { margin-top: .7rem; font-family: "Pretendard Variable", "Pretendard", "Noto Sans KR", -apple-system, "Malgun Gothic", sans-serif; font-size: .8em; }
.rtlty__content :is(h1, h2, h3, h4, h5, h6) { --risu-font-family: var(--rtlty-font-body); font-family: var(--rtlty-font-body); }
@media (max-width: 900px) { .rtlty__frame { padding: 4px; } }

/* ── 배색과 소재: 이 블록만 바꾸면 같은 분류의 다른 변주가 됩니다. (글래스) ── */
.rtlty {
  --rtlty-blur: blur(16px) saturate(1.25);
  --rtlty-bg-edge: inset 0 0 0 1px rgba(255, 255, 255, .13), inset 0 1px 0 rgba(255, 255, 255, .18);
  --rtlty-bg-fill: linear-gradient(160deg, rgba(255, 255, 255, .07), rgba(255, 255, 255, .015) 65%);
  --rtlty-paper: rgba(16, 17, 22, .4);
  --rtlty-paper-user: rgba(28, 29, 36, .42);
  --rtlty-rule: rgba(255, 255, 255, .07);
  --rtlty-ink: #eeece6;
  --rtlty-muted: rgba(230, 228, 222, .66);
  --rtlty-accent: #e0cba6;
  --rtlty-dialog: #ffffff;
  --rtlty-stamp: rgba(255, 255, 255, .85);
  --rtlty-shadow: rgba(0, 0, 0, .25);
  --rtlty-line: rgba(255, 255, 255, .13);
  --rtlty-tint: rgba(255, 255, 255, .07);
  --rtlty-edit-bg: rgba(10, 11, 15, .5);
}

@import url("https://fonts.googleapis.com/css2?family=Gowun+Batang:wght@400;700&family=Nanum+Pen+Script&display=swap");

/* 바깥 래퍼: 메시지 폭을 확보하고 가운데 정렬합니다. */
.risu-chat > div {
  padding: .9rem .75rem;
  margin: auto;
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
}
.risu-chat > div > div {
  width: 100%;
  margin: auto;
  display: flex;
  justify-content: center;
}

/* 글꼴과 크기: 본문 글자 크기는 --rtlta-font-size로 바꿉니다. */
.rtlta {
  --rtlta-bg-fill: transparent;
  --rtlta-blur: none;
  --rtlta-bg-edge: none;
  --rtlta-font-body: "Gowun Batang", "Noto Serif KR", serif;
  --rtlta-font-display: "Nanum Pen Script", "Gowun Batang", cursive;
  --rtlta-font-size: 16px;
  --rtlta-line-height: 1.9;
  --rtlta-para-gap: 0;
  --rtlta-dialog-weight: 700;
}

/* 본문: RisuAI 기본 색·글꼴 변수에 테마 값을 연결합니다. */
.rtlta {
  --risu-font-family: var(--rtlta-font-body);
  --FontColorStandard: var(--rtlta-ink);
  --FontColorBold: var(--rtlta-ink);
  --FontColorItalic: var(--rtlta-muted);
  --FontColorItalicBold: var(--rtlta-muted);
  --FontColorQuote1: var(--rtlta-muted);
  --FontColorQuote2: var(--rtlta-dialog);
  position: relative;
  isolation: isolate;
  width: 100%;
  min-width: 0;
  color: var(--rtlta-ink);
  font-family: var(--rtlta-font-body);
  font-size: var(--rtlta-font-size);
  line-height: var(--rtlta-line-height);
}
.rtlta, .rtlta *, .rtlta *::before, .rtlta *::after { box-sizing: border-box; }
/* 바깥 래퍼 보정(.risu-chat > div > div)이 테마 루트를 flex로 바꾸지 않게 루트 배치를 고정합니다. */
.rtlta.rtlta { display: block; }
.rtlta__content {
  min-width: 0;
  color: var(--rtlta-ink);
  word-break: keep-all;
  overflow-wrap: anywhere;
}
.rtlta__content .chattext {
  --tw-prose-code: var(--rtlta-ink);
  --tw-prose-pre-code: var(--rtlta-ink);
  --tw-prose-pre-bg: var(--rtlta-tint);
  max-width: none;
  color: var(--rtlta-ink);
  font-size: var(--rtlta-font-size) !important;
  line-height: var(--rtlta-line-height) !important;
}
.rtlta__content :is(p, li, td, th, blockquote) {
  font-size: var(--rtlta-font-size);
  line-height: var(--rtlta-line-height);
}
.rtlta__content p { margin: 0 0 var(--rtlta-para-gap); }
.rtlta__content p:last-child { margin-bottom: 0; }
.rtlta__content :is(h1, h2, h3, h4, h5, h6) {
  --risu-font-family: var(--rtlta-font-display);
