  padding: .5em .7em;
  color: var(--rtsf-ink);
  border-bottom: 1px solid var(--rtsf-line);
  text-align: left;
  vertical-align: top;
}
.rtsf__content th { font-weight: 700; }
.rtsf__content img { display: block; max-width: 100%; height: auto; margin: .75em auto; }
